quests[78974] = { id = 78974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beetle-Minded" }
quests[78978] = { id = 78978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raising a Stink", description = "Those clues add up to an ugly story, {name}.\n\nThat map shows the Crown's got a heavily guarded base of operations in Silverpine Forest. And between that memo and formula, it looks like they're cooking up something intoxicatingly toxic.\n\nI've got a gal that can get us some... artisanal goods... to deal with the Crown. I'll go talk to him and meet you outside Shadowfang Keep.", completion = "There you are, right on time.\n\nI've got a plan to deal with this chemical conspiracy.", objectives = "Meet Detective Snagglebolt at the entrance to Shadowfang Keep in Silverpine Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78979] = { id = 78979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loving Yourself, Your Way", description = "While visiting this gala, I am staying at the Razor Hill inn. It may not look like much, but it is surprisingly comfortable!\n\nWhy don't you see if they have any extra beds you could use?\n\nI think I will have a bit of a rest too... Right... here...", progress = "<Ning is quietly snoring.>", completion = "...Huh? Oh! Welcome back, did you enjoy your rest?\n\nOn any other day, you do great deeds for others.\n\nToday you have done something great for yourself. And that is the best gift of all.", objectives = "Take a nap in the inn at Razor Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78980] = { id = 78980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take a Look Around", description = "Here at the Gala of Gifts, we have many wonderful artisans crafting gifts just for you and your loved ones. But don't take my word for it--there are plenty of attendees enjoying the festivities as well!\n\nGo, speak to the visitors, and see what the artisans have to offer. Maybe you will find the perfect gift!", progress = "Are you having a good time?", completion = "As you can see, there are plenty of gifts to be given!\n\nGo get a gift for someone you care about!", objectives = "Meet the vendors and visitors at the Gala of Gifts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78981] = { id = 78981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Love is in the Air", description = "Smell these roses! My partner got them for me at the Gala of Gifts.\n\nInterested in seeing things yourself? Head to Durotar. There are gifts, and food, and you should taste the chocolate, it's delicious!", completion = "Welcome to the Gala, friend!\n\nWould you like to hear more about our specialty chocolates?", objectives = "Visit the Gala of Gifts in Durotar, near Rocktusk Farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78982] = { id = 78982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Smell Trouble", description = "You smell that funny odor too? Smells like smoke, cheap cologne, and alchemical nonsense. You ask me, I think the Crown Chemical Co. is up to something. Want to help me get to the bottom of it?\n\nWell, take a look at my pal here. Sure, he looks like a pooch, but this is O.D.I.E.! The Olfactory Detection and Inspection Engine! With this little fella, you and I can sniff out whatever the Crown is plotting from a mile away!\n\nAre you in? I could use a good partner to solve this.", progress = "Sure, O.D.I.E. can sniff out the clues, but you still gotta piece 'em together.", completion = "Poisonous perfumes? Revenge for kicking 'em out of the city?\n\nSeems like Apothecary Hummel is cooking up something sinister. This could get ugly.", objectives = "Use O.D.I.E.'s Remote Control to find clues around Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78983] = { id = 78983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unwelcome Gift", description = "I have a sinking suspicion there are spies from the Crown Chemical Co. among us. But I know that you know that O.D.I.E. here knows how to latch onto their scent!\n\nBut let's not bother anybody just here to have a good time, all right? Keep your nose peeled for chemicals, and make sure we're hitting the right targets.", progress = "Follow your nose, pal! Anyone who stinks could be a suspect.", completion = "Yeesh, {name}, you reek!\n\n\n\nEven worse! I reek!\n\nWell at least we've given some peace to the gala. I'd hate to have the Crown ruining the celebrations.", objectives = "Kill 8 Crown Chemical Co. members around Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78984] = { id = 78984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "Looks like Hummel's got some security. But don't worry, I came with some special gifts to deliver.\n\n<Snagglebolt points to the unmarked box.>\n\nBombs. I got bombs.\n\nPlaytime's over. Take those bombs and toss 'em at the Crown and their supplies. Let's give them a look at what genuine craftsmanship can do. Once we've cleared out their operations, we can move in on Hummel.", progress = "We need to put a stop to this before the Crown pulls off their smelly sabotage.", completion = "Man, I love a good fireworks show! Great job, {name}. That oughta slow them down.\n\nNow there's just Hummel to deal with.", objectives = "Use the Artisanal Bon-Bombs to destroy Crown supplies and kill Crown members.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78985] = { id = 78985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stench of Revenge", description = "We're never gonna see an end to this unless we take on the boss himself.\n\nLook, Apothecary Hummel is holed up in Shadowfang Keep with his cronies. He's working on a new batch of poisonous perfumes, and they'll knock out all of Orgrimmar if we let him finish his research.\n\nYou go do what you do best, pal. Get in there and foil his schemes before we're all lavender-scented corpses.", progress = "You ready to see what Hummel is cooking? I guarantee you it's not as pretty as it smells.", completion = "Sounds like you got there just in time--great work.\n\nThis would have gotten real ugly if Hummel poisoned the entire gala.\n\nLet's just call this our gift to them, eh?", objectives = "Speak to Snagglebolt to enter the Crown Chemical Co. battle and defeat Apothecary Hummel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78986] = { id = 78986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getaway to Scenic Grizzly Hills!", description = "Good morrow! Today's special portal is a magical getaway to the majestic forests of Northrend!\n\nAlthough perhaps I could beg you for a favor. You seem the adventurous type. \n\nI could use your help in delivering some flowers from Grizzly hills to a beautiful woman named Laverne. \n\nI would do it myself but... Well, you see, she is rather intimidating in her beauty.", progress = "The mage conjuring portals?\n\n<Laverne giggles.>\n\nLet me see.", completion = "This gala is quite marvelous for making new discoveries...\n\n<Laverne idly picks at the flowers while staring in the direction of Aurora.>", objectives = "Take the Scenic Getaway Portal to Grizzly Hills to pick a bouquet of flowers for Laverne.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78987] = { id = 78987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getaway to Scenic Nagrand!", description = "Good morrow! Today's special portal is a magical getaway to the great plains of Nagrand!\n\nWould you, perchance, be interested in a proposition? I will lend you my camera if you could deliver any photographs you take to my dear friend Karn.\n\nHe has been adrift in Nagrand as of late, lost in his own thoughts. As stubborn as he is, I'm sure he will appreciate the company. I would do it myself, but I must maintain the portals here.", progress = "How is Karn? When last I saw him, he seemed drowned in regrets and loneliness.", completion = "He asked you to do WHAT?\n\nHe knows that Laverne is--ARGGH! This is my justice, I suppose, for not acting sooner on matters of my own heart.\n\nNo matter. Everything is fine, Aurora, this is fine...\n\nErm, thank you regardless, {name}. The thorns of my roses need not rest in your hands. I will find another way to gain Laverne's attention.", objectives = "Take the Scenic Getaway Portal to Nagrand, then take pictures of wildlife for Karn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78988] = { id = 78988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getaway to Scenic Feralas!", description = "Good morrow! Today's special portal is a magical getaway to the sunny beaches of Feralas! The Steam Pools resort is having a lovely celebration and all are invited!\n\nUnfortunately, some of our festival attendees who took this portal earlier left their gifts here at the gala.\n\nCould you perchance help me return them? I will meet you at the beach and together we shall be able to determine which gifts belong to whom.", progress = "There are so many places in Azeroth to escape to! Everywhere you look, there's something new to discover.", completion = "You are wonderfully helpful, {name}. You have brightened the spirits of many people by returning their gifts to them.\n\nAnd what an array of gifts they were! Perhaps the language of love looks different to everyone.", objectives = "Take the Scenic Getaway Portal to Feralas, then deliver the lost gifts to the correct recipients.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78989] = { id = 78989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gift of Self-Care", description = "The eyes of a tired adventurer.\n\nA {class} that does many great deeds for many people. When was the last time you did a kind gesture for yourself? \n\nPerhaps now is the time. Look into your heart. \n\nWhat do YOU desire?", progress = "Love is a blessing, especially if it comes from within.", completion = "Let us begin your journey to self-love.", objectives = "Speak with Ning to discover your heart's desire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78990] = { id = 78990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gift of Relief", description = "You adventurers are known to carry heavy burdens. There will be no better time to confront them than now. \n\nI saw a veteran somewhere around here. There is a chance he may know what it means to cope with stress.\n\nPerhaps he has insight to teach you.", progress = "I've seen men die of stress, you don't want to bottle it up every day.", completion = "Feeling better? \n\nYou must take care of your body after a tough day. Be good to your head and heart and they'll be good to you.", objectives = "Speak to Tokag Bonebreaker at the Gala of Gifts, then relieve your stress in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78991] = { id = 78991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gift of Relaxation", description = "Love is a gift, yes. But it is also a gift that you can give yourself.\n\nSometimes, the best way to love yourself is simply to relax.\n\nI met a troll across the Southfury River who seems particularly wise in this regard. Perhaps you could ask her for insights in the art of relaxation.", progress = "True love is letting ya guard down. Let yourself relax, you'll see what I mean.", completion = "Ya feel renewed, don't ya? We all got ta relax from da problems in our lives.\n\nRelaxin' has helped me re-discover who I was. Changed my whole life! I used to have tusks out to here and a mohawk, bwahaha! What a stupid boy I was.\n\nDid ya discover anyting about yourself?", objectives = "Speak with Jaz the Reborn about relaxation, then relax by Southfury River in the Northern Barrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78992] = { id = 78992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loving Yourself, Your Way", description = "If it's a challenge you're after, I think I have an idea.\n\nI saw a boastful champion heading toward Razor Hill. You could challenge him to a duel.\n\nThis would satisfy your desire and perhaps teach him a valuable lesson in humility.", progress = "How fares your challenge?", completion = "On any other day, you do great deeds for others.\n\nToday you have done something great for yourself. And that is the best gift of all.", objectives = "Defeat Poggchug Ragethrower in a duel near the road to Razor Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78993] = { id = 78993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loving Yourself, Your Way", description = "A full belly is a happy belly!\n\nThere is plenty of good food and drink right here at the gala. Why don't you buy yourself something nice?", progress = "Have you had your fill of treats? I love the fruits, myself.", completion = "On any other day, you do great deeds for others.\n\nToday you have done something great for yourself. And that is the best gift of all.", objectives = "Consume Packages of treats from vendors at the Gala of Gifts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78995] = { id = 78995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truffle Shuffle" }
quests[78996] = { id = 78996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons and Warriors", description = "Gorloc raiders have been slaughtering these farmers and stealing their pearls. They seek our protection, but we may not be enough.\n\nI know of others nearby who can help. Seek them out and request their aid. If they are hesitant, offer them the promise of pearls as payment.\n\nWe will also need to arm these farmers so they can defend themselves. Search for spare weapons and equipment that they might be able to use.\n\nI will go with the farmers and train them as best I can.", completion = "Good work. I'm glad you were able to recruit some fighters. It is worse than I expected, and we will need every one we have.", objectives = "Collect 3 weapon crates and recruit 5 warriors from Freywold Village and Dhar Durgaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78997] = { id = 78997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilfered Pearls", description = "The pearls that these farmers harvest are their only source of livelihood. Some of these earthen even look at pearl farming as their primary reason for existing.\n\nThe gorlocs continue to pilfer pearls at every opportunity. As you eliminate the gorlocs, search them for stolen pearls. Let us recover as many as we can.", progress = "We need to return these pearls to the farmers.", completion = "Thank you {name}. Eliminating the gorloc threat was just one of our objectives here. Giving the farmers their lives back is another.", objectives = "Retrieve 8 Pilfered Pearls from gorlocs at the Glimmering Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78998] = { id = 78998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frontline Farmers", description = "Most of the farmers are already out in the field, defending their positions. I have trained them as best I could given the circumstances, but they are still wielding farming tools. \n\nI need you to distribute the weapons you gathered to those on the frontlines. While it may not markedly improve their combat ability, at least it will boost their confidence that they are not alone in this fight.", completion = "Excellent. As long as they fight together and for each other, I believe we will be victorious.", objectives = "Distribute 3 weapon crates to the pearl farmers at Glimmering Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[78999] = { id = 78999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of a Hero", description = "It seems the gorlocs have been bolstering their forces with summoned elementals. That explains how they were able to overrun the farmers so easily.\n\nIt will take all of our strength to hold off the colossi already in the field. I need you to stop any new elementals from being created.\n\nElementals of this size and power can only be created by the most powerful of gorloc shaman. Seek them out behind enemy lines and eliminate them.\n\nThis should end the gorloc threat to the farmers once and for all.", completion = "Thank you for your aid stranger. Without you, none of this would have been possible. You have given us back our livelihood today, and our hope.\n\nTake this as a small token of our gratitude. It is not enough, but it is all we can offer. Know that you will always be welcome among our people.\n\nLet us now turn our attention to Aggartha.", objectives = "Defeat the three gorloc shaman leaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79006] = { id = 79006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faction Switch", description = "Default" }
quests[79009] = { id = 79009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Harbinger", description = "We are in need of your aid once more, champion. A mysterious figure moves within the shadows. The Harbinger...\n\nLet us speak in the Chamber of the Guardian. I've asked Alleria to meet us there as well.", progress = "A Radiant Song, a Dark Heart, and this mysterious Harbinger... What could it all mean?", completion = "We know Iridikron gave the Dark Heart to the Harbinger. But what the Dark Heart is, what the Harbinger plans to do with it... Those are mysteries still.\n\nAnd the Radiant Song. Its timing is no coincidence.\n\nThis matter can no longer wait. That is why I've asked you and Alleria to investigate.", objectives = "Meet Khadgar and Alleria in the Chamber of the Guardian in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79010] = { id = 79010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Door to the Ren'dorei", description = "If this investigation involves the Void, it would be wise to consult the void elves. We must head to Telogrus Rift and report the situation.\n\nI'll speak with Umbric. He'll be able to mobilize the Riftwalkers to our cause.", completion = "We'll need to hear the Riftwalkers' reports before starting our own investigation. Perhaps there will be something that tells us where to begin.", objectives = "Follow Alleria to Telogrus Rift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79011] = { id = 79011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riftwalker Reports", description = "The Riftwalkers are tasked with investigating all void activity that appears on Azeroth. A most vital duty, given how dangerous this dark force can be. And I speak from experience.\n\nMany of them were sent out on assignment to investigate recent fluctuations. I've been told they just arrived back, but have yet to hear their reports.\n \nWould you check in on them while I speak with Alleria?", progress = "Let me know when you have those Riftwalker reports.", completion = "Thank you for gathering reports. Unfortunately, the Riftwalker from Northrend has yet to return.\n\nShe was investigating void activity in Galakrond's Rest. Given that location's connection to the Dark Heart, I'd suggest you search for her. \n\nLet's just hope our Riftwalker is still around to give you her report.", objectives = "Gather reports from Riftwalkers in Telogrus Rift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79012] = { id = 79012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracks in the Void", description = "Telogrus Rift has always been extremely sensitive to cosmic shifts. It makes for a rather precarious homestead, but the void elves have... few options available to us.\n\nThe recent influx in void energies has resulted in unstable rifts opening sporadically. And with so many investigating Azeroth, I'm having trouble finding Riftwalkers to deal with them.\n\nCould you close any unstable void rifts you find along your path?", progress = "Normally the Riftwalkers would be the ones to mend these sort of anomalies. But I wouldn't want to distract from their current investigations.", completion = "Excellent work.\n\nThose unstable void rifts threaten more than just our reality. If left unchecked, they would spread rampantly like little cosmic prions. No reality, no possibility, no truth that could possibly be would be safe from them.\n\nWhich is all to say, you did us quite the favor by closing them.", objectives = "Close 5 Unstable Void Rifts in Telogrus Rift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79013] = { id = 79013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galakrond's Unrest", description = "Galakrond's Rest. Where the Dark Heart was first empowered by Iridikron. We don't know what power the relic holds, but we do know that the Harbinger now wields it.\n\nAnd now one of our Riftwalkers is missing, right where it all began.\n\nI don't believe this is a coincidence, {name}. Let's travel to Northrend and search the area.", completion = "Time to find our Riftwalker. And, if we're lucky, discover a clue about the Dark Heart and this Harbinger who wields it.", objectives = "Meet Alleria at Galakrond's Rest in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79014] = { id = 79014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walk a Mile in Her Shadows", description = "I don't often work with the Riftwalkers. I prefer to handle missions alone. Still, I will not abandon one of them.\n\nI cannot yet sense the Riftwalker's presence. Our best path forward is to retrace her steps. \n\nWhich means following the shadows.", completion = "We now know why the Riftwalker didn't report back. She's turned against us and serves only the Void now.\n\nThough I wouldn't be surprised if the Harbinger had a hand in this.", objectives = "Uncover the void presence at Galakrond's Rest in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79015] = { id = 79015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Descension", description = "What are these void spawn doing here? Could it be the Harbinger's doing? Some power of the Dark Heart?\n\nWell. I do not mean to stand idly by.\n\nWe must confront the Riftwalker. I don't think she will see reason now, but perhaps she can tell us something.", progress = "What would the Harbinger want with Ulduar?", completion = "It's my charge to teach the ren'dorei to withstand the Void's whispers. If only I had gotten to the Riftwalker before the Harbinger did...\n\nNilara. Her name was Nilara, wasn't it.", objectives = "Confront the missing Riftwalker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79016] = { id = 79016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of the Void", description = "Make no mistake, {name}. I know this is a trap. But if there's any chance this leads us to the Harbinger, we must take that risk.\n\nBe at the ready. We venture forth.", completion = "Eredath. I never thought I would return here. Not after the Legion was finally defeated. Not after....\n\nWhy would the Harbinger bring us here?", objectives = "Travel to the Triad's Conservatory in Eredath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79017] = { id = 79017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path Taken", description = "These apparitions before us. I believe they're... memories. My memories. Is this the Harbinger's doing? Or mine?\n\nWe need to explore. Discover why we were led here.", progress = "Suddenly, this all feels rather personal. The Harbinger must have a grievance against me. Or at least an... interest. Hm.", completion = "We're finding the Harbinger and leaving this place. Now.", objectives = "Witness Alleria's memories in Eredath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79018] = { id = 79018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And Be One Traveler, Long I Stood", description = "I sense another memory ahead.\n\nWhile I'm loath to play along with the Harbinger's game, it's the only path forward for us.\n\nStill, we have faced just as many dangerous memories as peaceful ones. Prepare yourself.", completion = "The Harbinger dares to use my people, my memories, my love against me? \n\nThen she will know what it means to be my enemy.", objectives = "Investigate the final memory at the Triad's Conservatory in Eredath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79019] = { id = 79019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defend Telogrus Rift", description = "No. Not the ren'dorei. Not Telogrus Rift. Not today.\n\n<Alleria tightens her grip on her bow.>\n\nThese ethereal forces are the same we encountered in Ulduar. The Harbinger must command them. \n\nI'll go ahead. Engage the enemies here.", progress = "My people can defend themselves, but even they will struggle against such an overwhelming force. We must aid them.", completion = "There's no end to these void spawn. But for now, we must turn our attention elsewhere.", objectives = "Defend Telogrus Rift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79020] = { id = 79020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Null and Void", description = "We must defeat that loathsome apparition of Turalyon.\n\nThe abomination's presence is intolerable. If left unchecked, it may destroy what remains of Telogrus Rift. \n\nI will end it with my own hands.", completion = "There was once a time when I wouldn't have hesitated. When I would have struck that apparition down with a clear heart. Even if it wore the face of my beloved.\n\nBut something changed. I changed...\n\nGo. Speak with Locus-Walker. It seems he knows more than we do.", objectives = "Defeat the Corrupted Memory of Turalyon in Telogrus Rift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79021] = { id = 79021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Radiant Warnings", description = "So she goes by Harbinger now, does she? How fitting.\n\nI no longer feel her presence, but make no mistake. Xal'atath's nefarious games continue. And Alleria is now a pawn upon her board.\n\nAs are you, champion of fate.", progress = "Telogrus Rift should no longer tempt Xal'atath. For now.", completion = "The Harbinger is Xal'atath? And she's already attacked Telogrus Rift. \n\nThis is most serious, {name}. I'm afraid we have no more time for investigations.\n\nIf Locus-Walker is right, the answer will lie within the Radiant Song. We must discover what it means.", objectives = "Deliver Locus-Walker's warning to Khadgar in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79022] = { id = 79022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mysterious Signal", description = "High Speaker Brinthe has sent an urgent missive for you, {name}.\n\nShe is eager to assist in the coming war effort, and is investigating a mysterious signal in the Deepforge Golemworks, a defunct golem manufacturing facility in the Ringing Deeps.\n\nCan you meet her there and provide your expertise?", completion = "{name}, thank you for coming so quickly. I could use your help once again.", objectives = "Meet Brinthe at the Deepforge Golemworks in the Ringing Deeps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79023] = { id = 79023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Small Friend, Big Plans", description = "I tracked down a distress signal that led me to this little maintenance machine. A curious find, but the real treasure is the defunct war golem facility to the southeast.\n\nIf we can start producing war golems again we'll be able to contribute to the war effort. Unfortunately, it's been overrun by a goblin salvage group. And we'll need to investigate and assess if the facility is functional.\n\nFortunately, I have a plan, and it involves our little friend here. Why don't you introduce yourself?", progress = "With your assistance, I think we can find a way to clear this place out.", completion = "Now that introductions are out of the way. Let's sneak our way into this facility.", objectives = "Introduce yourself to the maintenance machine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79024] = { id = 79024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Factory Recon", description = "ZZ-01-47 should be able to make its way in there without drawing too much attention.\n\nBut be careful! These goblins are hungry for raw materials. If they spot our bot, they won't show it mercy.", progress = "Zee-Zee shouldn't be in much danger, as long as she stays away from the big mechs.", completion = "So we're contending with a lack of power, materials, and a dangerous amount of goblins.\n\nIf I had pores like an outlander, they'd be excreting moisture right about now. Is that proper terminology? I've seen your skin weep moisture before. Remarkable.", objectives = "Employ ZZ-01-47 to scout the Golem Factory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79025] = { id = 79025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Plan Comes Together", description = "We have our work cut out for us, {name}. But I think, with Dagran's help, we can break this down and tackle it piece by piece.\n\nWhy don't you take us through what we've learned so far.", progress = "We're some of the greatest minds in... well Gundargaz, at least. We can figure this out.", completion = "We need to secure the Waterworks and get the Shadowvein Excavation site up and running before we head back to the factory.\n\nLet's get to work.", objectives = "Go over the plan with Brinthe and Dagran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79026] = { id = 79026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting the Works in Waterworks", description = "Overly enthusiastic kobolds, angry elementals, and a broken-down power plant. This place is in shambles!\n\nDo you spot those large wheels on each side? They should be moving, but they're not. We'll need to get those moving again if we want this place to come back to life.", progress = "I wonder if we could use this technology to rebuild the Stonewrought Dam? Wouldn't that be something.", completion = "Wowiee look at it go! \n\nJust a fraction of Azeroth's power, harnessed for its protection.", objectives = "Get the Waterworks running again.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79027] = { id = 79027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Trepidation", description = "<ZZ-01-47 twitches back and forth, sensors scanning unceasingly. They seem afraid of this area, if they're even capable of feeling fear. Maybe clearing out some of the elementals will set them at ease.>", progress = "I appreciate what you're doing for Zee-Zee.\n\nAnd they appreciate it, too.", completion = "Thanks. I'm sure Zee-Zee appreciates it. When we're done here you can find them at the Shadowvein Extraction site.", objectives = "Defeat elementals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79028] = { id = 79028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Require More Minerals", description = "Zee-Zee is ready to help you get the Shadowvein site up and running again.", progress = "<Zee-Zee emits an inquisitive beep.>", completion = "<Zee-Zee whistles in relief. It seems they were not happy with the subpar maintenance standards here.>", objectives = "Get the Shadowvein site up and running.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79029] = { id = 79029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Sabotage", description = "We're back, and we're ready.\n\nYou and ZZ-01-47 head in and cause some mayhem. Blow stuff up and make a mess that will draw them out of the manufacturing bay. I'll use the commotion to sneak inside. Join me when you're able, and we should have a chance at reactivating the facility and driving them out.\n\nWe don't need to defeat them all. Defeating the Darkfuse leader supervising this operation should break their resolve.\n\nThe Darkfuse lackeys will clear out when the coin stops flowing.", completion = "It was touch and go there for a bit. But if anyone could seize a victory out of this, I knew it would be you.\n\nPlease return to the Emissary in Dornogal and communicate our victory. Go with my thanks, and with the knowledge that the Machine Speakers are indebted to you. Again.", objectives = "Wreak havoc, gain access to the manufacturing bay, and restart the facility.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79030] = { id = 79030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Voice of the Speakers", description = "Please take word of our victory to Alleria in Dornogal. I'm sure our allies will be pleased to hear what we can provide for the war effort.", completion = "What amazing news, {name}!\n\nThe War Golems awaken, and march against our enemies once again, just like in times past.\n\nYour contribution to the cause of the Machine Speakers, and to all of the Earthen, will not be forgotten.", objectives = "Return to Alleria in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79074] = { id = 79074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summoning All Soldiers!", description = "The Artisan's Consortium has struck one final deal with the quartermasters of the Gladiator's Refuge!\n\nIn addition to the usual selection of powerful combat equipment they offer, worthy combatants can purchase tokens that can be used in Crafting Orders or one's own crafts to certify the equipment for use in battlegrounds and arenas!\n\nPresent this brochure to Calderax to receive two complimentary Trophies of Conquest, on us!\n\n- Rabul", completion = "<Calderax grumbles something under his breath before proceeding with a very well practiced speech.>\n\nHere are your trophies, as promised. Use them when crafting your own equipment or submitting Crafting Orders and the gear will be comparable in power to what I offer. It is perfect if you are looking for something highly specific or imbued with a certain embellishment... and are willing to put in some extra work.\n\nQuestions? Take them to the Artisan's Market.", objectives = "Deliver the brochure to Calderax in the Gladiator's Refuge of Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79082] = { id = 79082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Superbloom" }
quests[79085] = { id = 79085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pile of Fish", description = "<A pile of fish, perhaps these could be transported by cart back to Seraphine Seedheart.>", objectives = "Load 4 Fish onto Fish Cart-Pusher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79087] = { id = 79087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pile of Clams", description = "<A pile of clams, perhaps these could be transported by cart back to Seraphine Seedheart.>", objectives = "Load 4 Clams onto Clam Cart-Pusher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79089] = { id = 79089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consecrated Cleanup", description = "Our Veneration Grounds have been desecrated. Its beauty marred. \n\nIt's going to take a bigger effort, but I would appreciate anything you can do to cleanup our grounds.", progress = "I wish you could have seen this place before the Kobyss arrived.", completion = "Thank you, {name}. It may not have seemed like much, but this is one of our most sacred places. \n\nWe remember our dead here. We... have a lot to remember.", objectives = "Restore the Veneration Grounds in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79105] = { id = 79105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breach", description = "As much as I'd love to hunt Xal'atath down, our first priority must be securing civilians. \n\nRescue whoever you can and tell them to head to the landing nearby. I'll find mages to teleport everyone to safety.", completion = "That's the first group evacuated. But we're not done yet.", objectives = "Send civilians to the landing for safety.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79106] = { id = 79106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rupture", description = "Follow me. We'll work together to find any others in need of rescuing.", progress = "The nerubians are capturing anyone they can and stringing them up in webs. Make sure to free whoever you find before moving on.", completion = "Looks like we saved who we could. Let's just hope the other rogues escaped.", objectives = "Save Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79107] = { id = 79107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "After the Storm", description = "Turalyon and Geya'rah are training our new earthen allies as ground forces. But we will need more than that. We will need the Stormriders. \n\nMany were lost in the infiltration of the Stormperch and more to the nerubians. Their leader, Stormward Baelgrim, died valiantly.\n\nThe surviving Stormriders are being cared for at a triage station nearby. We need to do whatever is necessary to get them and their rooks back in the air. They will be the earthen's most potent weapon in the battles to come.", completion = "I'm sorry about Shraubendre. She was just protecting me. And I lied to protect her.\n\nBut you truly don't intend to take her away? You just want to summon more stormrooks?", objectives = "Check on the Stormriders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79108] = { id = 79108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeds of Evil", description = "{class}, some of the shadowleaf plants are more... wrong than the rest. I don't know how to describe it better.\n\nMy idiot brother, Tomothy, was supposed to help me get rid of these, but I haven't seen him and I can't wait.\n\nClearly we don't want these to reproduce so I want you to cull as many as you can find, and then take their seeds. We'll burn those in holy fire to make sure we've cut off the infestation.", progress = "Did you cull those plants?", completion = "Good job culling those plants. Now, if only my lazy brother would show up for work.", objectives = "Collect Corrupted Shadowleaf Seeds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79109] = { id = 79109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Follow Miral", description = "Tomothy's lynx, Miral, has been bugging me. I don't know what she wants but it is unusual to see her without my brother. She's a great farm cat, but she's still a cat, so maybe she's just bored with Tomothy today? I don't know. Maybe Tomothy got into some sort of trouble.\n\nCan you find out what is bothering her for me?", progress = "<Miral looks at you as if expecting something. You are being judged.>", completion = "<Miral lets out a pleased sound and purrs at you.>", objectives = "Discover what is bothering Miral Murder-Mittens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79110] = { id = 79110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save Tomothy", description = "<Miral looks at you expectantly then looks at the ruins, then back to you, then to the ruins. You get the sense she wants you to go over there. Perhaps this is where Tomothy got lost?>", completion = "You saved my idiot brother from the darkness! Thank you.", objectives = "Save Tomothy Hillhelm from The Grasping Darkness.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79111] = { id = 79111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Lynx" }
quests[79114] = { id = 79114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beautification Project", description = "A fine enough job, for one of your... ilk.\n\nIf you wish to keep breathing, I suggest you continue to assist us. It may even prove lucrative for you, if you comply.\n\nRak-Ush's former master allowed the stagshells to run feral, and abandoned the hollows to decay. Over time, invasive plants have infested the old stagshell hollows.\n\nFind a way to clear them. I don't care how.", progress = "It would be unwise to return to me with an unfinished job.", completion = "Hm. It'll do.", objectives = "Clear the Stagshell Hollow of Overgrown Plants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79115] = { id = 79115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expert Consultant", description = "You alone are no longer sufficient. We require additional assistance, and the jawcrawlers and threadlings also need oversight.\n\nThe niffen settlement, Mmarl, is not far. However, past forced conscription attempts have failed. Nerubians are now forbidden within the settlement. We need someone to communicate in our stead.\n\nGo and barter with the rats. Come back with able bodies.", completion = "The nerubians want our help again? I'd like to hear this...", objectives = "Speak with Mmarl's leader about recruiting swarmhands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79116] = { id = 79116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spider Optics" }
quests[79117] = { id = 79117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bright Young Niffen", description = "You need swarmhands, huh? \n\nLast time the nerubians wanted our help, they tried to force us. They're terrible negotiators! All we wanted was a little quid pro quo.\n\nWe've got several arachnologists, but most of them are busy keeping the flyers at bay. I'm sure they won't refuse an opportunity to study some swarmbeasts up close and personal! \n\nMaybe if you lighten their workload, they'll take you up on your offer.", progress = "Have you found anyone yet?", completion = "See? All we wanted was a little something in exchange.", objectives = "Find 6 Niffen Arachnologists outside Mmarl to join Rak-Ush.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79118] = { id = 79118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rak-Ush Under New Management", description = "Well, you got your swarmhands. \n\nWhat are you still doing here? Go on then, you don't need my permission!\n\nMake sure the nerubians treat them fairly, now.", completion = "Excellent.", objectives = "Return to Vix'aron in Rak-Ush.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79119] = { id = 79119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Rough to Be a Bug!", description = "Anub'azal gave his orders! We are the new masters of Rak-Ush! Yet Vix'aron decided to throw a tantrum and destroy our barn instead.\n\nSince this imbecile refuses to follow orders, perhaps you will, overcrawler. Maybe then we will decide not to kill you for eavesdropping. And recompense, I suppose.\n\nGo. We are to restore the stagshell hollows and fill them with swarmbeasts.", progress = "We need this barn in an operational state!", completion = "Surprisingly, you've proven yourself useful.", objectives = "Clean up the barn in Rak-Ush.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79120] = { id = 79120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beetle in a Haystack", description = "There are still feral stagshells on the outskirts of Rak-Ush.\n\nThis scent grenade should be sufficient in stunning the beasts and alerting the niffen to their location.\n\nOnce they are stunned, one of the rats will take them back to their hollow.\n\nCapture them and bring them back. We will be waiting.", progress = "We still require more stagshells.", completion = "Excellent work.", objectives = "Capture and return six Feral Stagshells to Rak-Ush.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79121] = { id = 79121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bug Test", description = "Oh, I'm sorry, did you think this was a one and done assignment? If you did, Vix'aron would gladly \"show you the door\", as it were. The stagshells will require constant maintenance. Food. Water. Those sorts of things.\n\nLoathe as I am to admit it, the niffen are much more skilled at caring for swarmbeasts than Vix'aron or I.\n\nThey can enlighten you on your duties, if this was not explanation enough.", progress = "Do not return to me until you have finished your lessons with the niffen.", completion = "I trust that wasn't too complicated for you?", objectives = "Speak to Aromash and care for the stagshells in Rak-Ush.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79122] = { id = 79122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarab Scouting", description = "The stagshells are of the utmost importance to Anub'azal's war campaign. We have a keen sense of smell, but only the stagshells are able to seek out valuable Kaheti truffles. \n\nThe truffles are a key ingredient in several... explosive elixirs, as it were. If you desire details, Aromash can give you more.", progress = "We need an abundance of truffles to ensure we are properly prepared.", completion = "That is all that is required of you.", objectives = "Use a Rak-Ush Stagshell to find 5 Kaheti truffles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79123] = { id = 79123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Permanent Hire", description = "Rak-Ush is beginning to look like a functioning swarmery.\n\nThe role of delegation has suited me and Vix'aron well. You will continue to aid the niffen. In return, you may keep a portion of the wealth the swarmbeasts produce. \n\nSaffrin has more detailed plans around the development of the swarmery. Go speak to him, I have nothing else to say to you.", progress = "You have not spoken to Saffrin yet, have you? Otherwise you would not be here.", completion = "These swarmbeasts aren't going to take care of themselves!", objectives = "Speak with Saffrin in Rak-Ush.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79124] = { id = 79124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conduit of the Southern Storm", description = "I'll tell you what I told Baelgrim when we last spoke. The binding of stormrooks is wrong. These creatures are as smart as any earthen. Some I'd say are smarter.\n\nBut... Lufsela seems to be different. If her stormrook follows her willingly, then perhaps others will make that choice as well if she summons them.\n\nTo summon rooks, we need Baelgrim's conduit. It's tucked away here somewhere. Have a look around, and maybe ask these pilgrims if they have seen it.", progress = "Have you found the conduit?", completion = "Not only was Olbarig once a Stormrider, but he served as Baelgrim's right hand as a Stormguard for a long time. Seems they had a falling out over the rooks.\n\nBut Olbarig says that the conduit will serve as a beacon. If the stormrooks of Skywall are willing, it will guide them through the storm. He also seems to think I should be the one to use it.", objectives = "Find the Conduit of the Southern Storm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79125] = { id = 79125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kalimdor Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!", completion = "Thank you for visiting, skyrider!", objectives = "Visit Lord Andestrasz in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79126] = { id = 79126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kalimdor Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Orgrimmar. He's looking for capable skyriders like yourself to compete in new races!", completion = "Thank you for visiting, skyrider!", objectives = "Visit Lord Andestrasz in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79127] = { id = 79127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Outland Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!", completion = "Thank you for visiting, dragonrider!", objectives = "Visit Lord Andestrasz in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79128] = { id = 79128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Outland Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Orgrimmar. He's looking for capable skyriders like yourself to compete in new races!", completion = "Thank you for visiting, dragonrider!", objectives = "Visit Lord Andestrasz in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79129] = { id = 79129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rook Rally", description = "Now that we've got the conduit all charged, I suppose it's time we joined everyone on the peak. \n\nThrall talked me through what to expect, but also said summoning the stormrooks will require me to trust my feelings and instincts.\n\nAn earthen trusting their feelings and instincts. That's... a challenge.\n\nYou will help me, right? I'm not a fighter, and it looks dangerous up there. \n\nIf anything happens to me, make sure Shraubendre makes it out safe. Please.", completion = "Well done. It seems the rooks of Skywall haven't just answered the call. \n\nThey were reaching out to us, and they have chosen their own riders for this new generation. \n\nI am honored to have played a role in the ritual.", objectives = "Safeguard the summoning ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79130] = { id = 79130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Northrend Cup Circuit", description = "It is time once again to test your mettle.\n\nMy bronze colleagues have traveled to Northrend to create more new challenges. We would like to see if any daring skyriders will complete the entire circuit!\n\nAre you up to the task?", progress = "Have you taken wing today?", completion = "You lead the way among your fellow dragonriders!  If you haven't already, see if you can improve your times in the Northrend Cup and earn the colors of the Riders of Azeroth.", objectives = "Fly through Northrend Cup courses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79131] = { id = 79131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Northrend Cup Begins", description = "Skyrider! You just missed Lord Andestrasz. He's looking for capable skyriders like yourself to compete in new races!", completion = "Thank you for visiting, dragonrider!", objectives = "Visit Lord Andestrasz in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79132] = { id = 79132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Northrend Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Stormwind. He's looking for capable skyriders like yourself to compete in new races!", completion = "Thank you for visiting, dragonrider!", objectives = "Visit Lord Andestrasz in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79133] = { id = 79133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Northrend Cup Begins", description = "Skyrider! Lord Andestrasz has left the Dragon Isles and is visiting Orgrimmar. He's looking for capable skyriders like yourself to compete in new races!", completion = "Thank you for visiting, dragonrider!", objectives = "Visit Lord Andestrasz in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79134] = { id = 79134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spring Awakening", description = "The citizens of Goldshire have reported frequent interruptions to their recent festivities. Something about being overrun by angry... ducks? Perhaps you could look further into this conundrum.", completion = "Yes! Yes, I think I have just the task for you...", objectives = "Speak with Zinnia Brooks at Goldshire in Elwynn Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79135] = { id = 79135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quacking Down", description = "Those dratted ducks! Do you mind scaring them off again? I simply cannot leave my golden egg unattended!", progress = "Have you sufficiently shooed those ducks yet?", completion = "Oh thank goodness. Those ducks are driving me mad!", objectives = "Scare off 10 ducks using the Horn of Honking.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79136] = { id = 79136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spring Awakening", description = "The citizens of Razor Hill have reported frequent interruptions to their recent festivities due to a duck infestation, of all things. Perhaps you could look further into this conundrum.", completion = "Yes! Yes, I think I have just the task for you...", objectives = "Talk to Sylnaria Fareflame in Razor Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79137] = { id = 79137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wall Between Us", description = "I know this fight was not ours, {name}. But I thank you for your assistance. It was with the Alliance's assistance that Lordaeron was cleansed and the favor has now been returned.\n\nI do not think I can hope for peace. Instead, I will hope that these efforts have led to at least an understanding of the plights of both Gilneans and the Forsaken.\n\nLet us meet with Lilian in Pyrewood Village. This celebration is not for us.", completion = "Not my idea of a normal request from a friend, but I'll never object to killing more of the Crusade.", objectives = "Speak with Lilian and Calia in Pyrewood Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79139] = { id = 79139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alone in the Dark", description = "My people do not think that this Black Blood is a threat to our world. It has sat dormant for ages, after all. Why should that change now?\n\nBut the world is changing more quickly than my people realize. The nerubians' decision to extract the Blood for their own ends is proof of that.\n\nThe nerubians hold a watchtower not far from here. The ones who survived the pit could not have gotten too far. We should give chase immediately.", progress = "<The spider looks at you expectantly.>", completion = "<The bizarre creature's eyes remain locked upon you, unwavering. It nudges something towards you--a scroll with a thick seal of violet wax.>", objectives = "Investigate the Eye of Ansurek.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79140] = { id = 79140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldbricking", description = "Is this what we are to rely on to help us defeat Xal'atath? The Unbound define themselves by their desertion. And the Oathsworn, for being made of stone, are pretty soft. City life hasn't done them any favors. \n\nWe've got a lot of work to do.\n\nGet down there and give these earthen a taste of what it's like to face a real threat. Try not to knock any \"offline,\" but a maiming here or there would send a strong message to the rest.", progress = "Don't go easy on them. They're made of stone after all.", completion = "You lit a fire down there, and we will continue to fan the flames. \n\nGo now, secure in knowing you have helped set these earthen on the path to glory. The nerubians won't know what hit them!", objectives = "Spar with undisciplined earthen trainees.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79145] = { id = 79145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metal and Stone", description = "While some of these recruits struggle with discipline, most have a strong work ethic. They only need training and the equipment to make the most of it.\n\nEarthen weaponsmiths and armorers have been working around the clock to equip this fledgling army. But we could use some help getting the new armaments into the hands of these trainees.", progress = "Check in with Vindicator Jaelaana. She is in charge of distributing the weapons though she can be rather stingy. Be sure she doesn't send too many off for hand-to-hand training.", completion = "Now they're starting to look like a real army. We'll continue with their training, but I believe you have more important matters to attend to.", objectives = "Equip earthen trainees for battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79146] = { id = 79146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ground Pounders", description = "The rooks and their chosen riders will need time to bond. \n\nPerhaps you should use this time to check in on our other trainees. \n\nThe Stormriders are the traditional army of the earthen, but many Unbound and Oathsworn have expressed willingness to fight at our side due to help in restoring their machines.\n\nAdelgonn, Geya'rah, and Turalyon are busy training them. Go and see if they need any assistance.", completion = "Someone save me from all this bickering. Alliance this, Horde that... \n\nI've never encountered anything like it in my thousands of years even amongst the Oathsworn and Unbound. If they committed half the energy they expend on posturing towards training, our task would be complete by now.\n\nSee what help you can offer my people. They need real mentorship if we are to be ready for the next nerubian offensive.", objectives = "Meet with Adelgonn, Geya'rah, and Turalyon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79147] = { id = 79147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight Training 101", description = "Now that all of our recruits are present, it's high time we took to the air. See what I did there? High time? No?\n\nRight then. We'll be puttin' these rookies through their paces. Startin' with the basics of aerial maneuverin' at speed, we'll do our best to simulate the kind of precision flyin' we might expect below ground. \n\nAfter that, we'll see what these rooks can really do--an I think Thrall and Lufsela have somethin' special cookin'.", progress = "Let's set a good example for these new riders. Lead them through the course as quick as ye can.", completion = "There you have it! Raw recruits made of stone, soarin' on the backs of birds made of lightnin'. Proof that ol' Kurdran can teach anythin' to fly!\n\nBut we're not done yet.", objectives = "Help Kurdran train recruits in aerial maneuvering.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79148] = { id = 79148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nibelgaz Refinery", description = "Quickly! Elementals have overrun the Nibelgaz Mine and the refinery crew are trapped down there with them. \n\nI am especially worried about my fused, Munderut. His memory is not the best these days. If you are a friend, rescue him and the refinery workers.\n\nHere, take this healing clay. It only helps a little, but it should be enough for any injured to make their way back. I wish we had a rejuvenating crystal, but that is the stuff of legends.", completion = "The workers told me that you helped them escape the refinery. Task complete! \n\nI'll take the clay back now. Gratitude.", objectives = "Rescue 6 Refinery Workers and look for Munderut.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79149] = { id = 79149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rampage in the Refinery", description = "Catastrophe! Oh, this is awful. Awful! Those accursed slag heap elementals are keeping my refinery workers from being able to do their jobs.\n\nDuty demands we carry on our work. These delays will not be tolerated. You look competent enough. Go on, get down there and get to work destroying elementals. Production must not be slowed!", progress = "Well? Did you destroy them? I need my crew back to work immediately!", completion = "What a terrible delay in production. The miners will have to work twice as hard to make up for lost time, I am afraid.\n\nIt is good you came around when you did. Those elementals are a menace. An awful menace!", objectives = "Kill 10 Rampaging Elementals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79150] = { id = 79150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thespians at the Proscenium", description = "When I wanted the Unbound to bring their plays to Dornogal, I didn't know what I would be up against. Or that my \"help\" would get in the way.\n\nMy old friend Brokfor keeps interrupting us with his perfectionism. We try to build a set, but he stops everyone to inspect each nail. We try to paint, he complains the colors do not exactly match... you get the idea.\n\nI think Brokfor needs his own project. Maybe... cleaning up the Proscenium? Go ask him to help and keep him occupied.", progress = "Have you helped Brokfor straighten up?", completion = "Excellent! Now we can perform our tasks without his perfectionism getting in the way.", objectives = "Help Architect Brokfor clean up the Proscenium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79151] = { id = 79151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Orphan's Request", description = "Wow, you look really strong! Would you be able to help me?\n\nMy parents were killed by the mean kobyss. When I came here, I left my favorite, most well loved teddy ever behind. \n\nCould you go get it for me?", progress = "I will make the kobyss regret ever setting foot in these lands.", completion = "Fine, fine. I guess I don't mind if you come help.\n\nYou do actually look big, and strong.", objectives = "Retrieve Alyza's Much Loved Teddy Bear from the Hungering Pool in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79152] = { id = 79152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutting the Pool", description = "The kobyss are... a bit larger than I expected, and I might--might, you understand?--have more trouble with them than I originally anticipated.\n\nKill any stupid fish-faces you see.", progress = "Yes, make them bleed. Make them pay!", completion = "You've killed a lot of them.\n\nI wouldn't mind if you killed more. Just saying.", objectives = "Kill 10 kobyss in The Hungering Pool in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79153] = { id = 79153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vae Victis", description = "Ah it's time.\n\nKill their leader. Salt his bones, take his head, and laugh as his tribe crumbles!\n\nSharpscale's last moments are upon him, and he doesn't even realize it yet. \n\nStupid fish-face.", progress = "His skull would make a good cup I think? Perhaps a mantle ornament?", completion = "Oh. This head is quite a bit more icky than I was expecting. You can keep that.\n\nYou are much more useful than I thought you would have been, {name}.", objectives = "Kill Sharpscale the Devourer and retrieve its head in the Hungering Pool in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79154] = { id = 79154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Final Goodbye", description = "Well, parents avenged, fish killed, more fish killed, biggest fish killed. \n\nPretty good day.\n\nI guess I should go burn stuff.", completion = "Thanks, {name}. I'll make sure to put in a good word with General Steelstrike for you. I know her well. \n\nWell, I met her once. \n\nWell, I saw her in the street.\n\nBut I did think about talking to her, so it's the same thing really.", objectives = "Help Alyza say goodbye in the Hungering Pool in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79156] = { id = 79156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Edicts", description = "Merrix and Adelgonn will be expecting an update. On my way here, I heard that they're all heading to the Proscenium to commit to the war officially. You should go and brief them on the readiness of the Stormriders.\n\nI'd like a moment with Zarein here. But we'll be along soon. And we'll be bringing Baelgrim's spirit with us.", progress = "This is a critical moment for all earthen.", completion = "Titans... what have they done?", objectives = "Report to Merrix and Adelgonn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79157] = { id = 79157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanic Failsafe", description = "So, the titans sent their ancient machines against their disobedient children.\n\nWould our creators have us protect the Coreway at the expense of all else? At the expense of Azeroth herself? Are we meant to preside over a road untraveled, leading to the world's dead heart?\n\nNo, today we are all Unbound, and we will fight for our freedom. For Azeroth!", progress = "None on this isle will be safe until that titan construct is dealt with. Go!", completion = "It was a trial by fire, but you've proven that the earthen of The Isle of Dorn are ready for the war to come. Where once there was discord, there is now unity of purpose. They are no longer Oathsworn or Unbound. They are united, just as we should be, against this darkness.", objectives = "Defeat the colossal titan construct.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79158] = { id = 79158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeds of Salvation", description = "These once obedient harvestbots have run amok and are wreaking havoc in our fields.\n\nThe success of our community depends on getting our seeds in the ground, but most of the seeds are in the hands of those harvesters!\n\nWould you venture into the fields, eliminate any rogue machines, gather the seeds, and finish the planting?", progress = "Have you planted the seeds?", completion = "You've truly done us a great service! Planting those seeds buys us valuable time until the harvestbots are repaired.", objectives = "Recover Harvest Seeds and plant 8 seeds in Seed-Ready Soil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79159] = { id = 79159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dereliction of Duty", description = "A moment, if you have one.\n\nOne of my lieutenants, Shinda Creedpike, did not report in at first bonfire. That may not seem like a large issue to you, but the Arathi in Hallowfall survive only because we follow orders and stand for our brethren.\n\nI am not cruel. I do not want to punish a man for his weakness in this terrible environment. Can you find him and bring him back? \n\nTake all the time you need.", progress = "Dawnsurge must have sent you.\n\nIt seems like my respite is over.", completion = "You're speaking my language, {name}. Plans give me structure and a goal to achieve.\n\nLet me think about the optimal way to relax.", objectives = "Find Shinda Creedpike at Mereldar in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79160] = { id = 79160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fishing is Good for the Soul", description = "I used to fish with my mother at the local pond when I was a child. It wasn't the fish that made the experience--my mother was famously terrible at cooking--but the tranquility and bonding time.\n\nPerhaps I could find a portion of that peace again here. There's a spot south of Mereldar that the others use to fish. I'll meet you there!", progress = "Maybe I can find peace in the act of fishing.", completion = "I wish we could have fished. But if today confirmed anything to me, I have relearned a valuable truth.\n\nIf I lay down my sword, these children would have to pick them up if they are to survive this place. They have known no other place than this land.\n\nThey will see our homeland. They must see our homeland.", objectives = "Meet Shinda at the fishing hole.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79162] = { id = 79162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burnout", description = "Please return to Commander Dawnsurge and give them my sincere apologies for my absence. I will submit myself for punishment for my trespass after my shift.", completion = "I will not institute any punishment for his absence. I'm simply glad you were there to support him when I could not.\n\nWe are living in times of prophecy, {name}. It is a curse I would not bestow upon anyone. We must do what we must to survive these days.", objectives = "Return to Endiri Dawnsurge in Mereldar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79165] = { id = 79165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Moment to Rest", description = "Good, you're both here. \n\nI have a favor to ask. \n\nFaerin's wandered off. I think it might help if you and your... disheveled friend here find her. \n\nShe'll be in Light's Redoubt.", completion = "<Anduin chews his lip, lost in thought.>", objectives = "Find Faerin near Light's Redoubt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79166] = { id = 79166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Pieces", description = "There was a time when I would have known what words to say to help her.\n\nBut now... they are as lost to me as everything else. \n\n<Anduin sighs.>\n\nThere must be something we can do. Her old Lamplighter companion, this Andari... would have had one of those tinderboxes, right? They seem important for funeral rites. \n\nI'll accompany Faerin back to Mereldar and meet you there. If you think there's hope of finding Andari's lost belongings... could you try to look?", progress = "There's no time to mourn. Not when there's fighting to be done. If you have time to mourn, you have time to train. \n\nTo make sure we don't lose anyone else.", completion = "You found their things? In all the darkness? \n\nThank you. \n\nAnd this, this is...", objectives = "Collect 8 Lost Personal Effects from enemies in the Harrowing Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79167] = { id = 79167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crowdsourcing", description = "Light's Gambit is an old and honored game. There's a reason so many Arathi play it! \n\nIt can teach you a lot about strategy. And it can tell you a lot about your opponents. \n\n<Faerin suddenly deflates.> \n\nBut we're still missing a few pieces that we need in order to play.\n\nSometimes, folks around Mereldar lend us pieces for a game. Could you ask around?", progress = "The rules are a bit lengthy but trust me... it's worth it!", completion = "We... might have gotten a bit ahead of ourselves.", objectives = "Collect 4 Game Pieces from Arathi in Mereldar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79168] = { id = 79168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light's Gambit", description = "It's fine! We can catch you up on the rest of the rules later!\n\nResolving combat is the most fun, anyway!\n\nYou and Anduin can team up against me. Perhaps with the both of you together, you'll stand a chance!\n\n<Faerin laughs.>", completion = "I hope you found that relaxing, too, {name}. I didn't realize how much we all needed a break.", objectives = "Grab the castle piece to start a game of Light's Gambit with Faerin and Anduin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79173] = { id = 79173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supply the Effort", description = "When shadow fell upon our town, many necessary supplies were taken in the cover of darkness.\n\nWith the light returning, it is time to rebuild, but first, we must retrieve what was lost. \n\nSearch the surrounding areas, recover any supplies that might be useful.", progress = "Have you recovered the stolen items?", completion = "You have recovered far more than we could have hoped.  I've set some of the extras aside for you to have.", objectives = "Recover various stolen items from the surrounding area to satisfy our needs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79174] = { id = 79174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infested Infestation", description = "These spore-afflicted beasts at Pillar-nest Vosh been a thorn in our side since setting up Faerin's Advance. They be spreading thick clouds of spores. I never be seeing anything like it!\n\nThey already attacked once. Won't be long till they attack again. If we got any hope of survivin', we need to cull dere numbers. \n\nGo to Pillar-nest Vosh and take some of those spore-afflicted beasts out!", completion = "With de number of those spore-afflicted beasts reduced, we bought more time ta think of a more permanent solution.", objectives = "Kill 12 spore-afflicted beasts at Pillar-nest Vosh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79175] = { id = 79175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Think I'm a Drone Now", description = "There, I have extended some goodwill. You have a little goblin friend. I know how much your kind clings to each other for warmth.\n\nAnd now you both will do things for me. First, I will provide you with my pheromone scent mark. It will keep my loyal soldiers from attacking you. It marks you as mine.", progress = "Don't waste my time. Are you ready to accept my mark? Step into the pheromone cloud with your {race} friend, and rub it on.", completion = "Your friend complains, but my mark will keep you relatively safe, except from Zev'kall's guards. They won't care about scent marks if they are already hostile to me.\n\nSo make the most of it, but take care.", objectives = "Allow Anub'azal to mark you with his pheromones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79176] = { id = 79176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opals and Runes", description = "You have certainly made my disaster of a day far less stressful, {name}. \n\nFor that, you have the thanks of the entire Forgegrounds and those who keep it running.\n\n<Vokgret winks as she gives you a knowing smile.>\n\nBevrusi was right to send you to me. Do tell her not to be a stranger now. I could use more friends from the Deeps.\n\nHere is her liquid opal. Give it to her with my compliments.", progress = "Everyone in the city is in need of something, and there is always someone with the means to acquire it.", completion = "I send you to a Machine Speaker to get us into the speakeasy, and you wind up aiding the market reeve of the Forgegrounds in some roundabout delivery and trading operation?\n\n<Merrix smirks coyly as he claps his heavy stone hands in applause. It is a much quieter sound than you would imagine.>\n\nWell done, my resourceful outlander.", objectives = "Trade the Vial of Liquid Opal for the Speakeasy Passrune from Bevrusi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79178] = { id = 79178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Play Hearthstone!", description = "It's time to play Hearthstone! \n\nHere's a starter pack -- open it up and add those cards to you collection. Then, if you can find a seat at the game table, then sit down with someone else and play!\n\nOr if you can't find a seat, then you'll want some Wild cards.... I didn't tell you this but there's a shady card dealer lurking around here somewhere.", progress = "Like the game so far? Give it a chance and play those cards!", completion = "How did you do? Had some good, clean fun I'm sure!", objectives = "Play 5 Hearthstone cards at a Hearthstone Game Table, or Wild Cards NEAR a Hearthstone Game Table.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79184] = { id = 79184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Hearthstone's Anniversary!", description = "\"Hearthstone's been played for ten years, can you believe it?\n\nI'm hosting Hearthstone games in Valdrakken, way up in the Seat of the Aspects. Come join us!\n\n-Farala, Master of Ceremonies\"", completion = "Welcome to the celebration! Now get out there and join the fun!", objectives = "Speak with M.C. Farala in Valdrakken, in the Seat of the Aspects.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79186] = { id = 79186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Hearthstone's Anniversary!", description = "Hearthstone's been played for ten years, can you believe it?\n\nFarala, Master of Ceremonies, is hosting Hearthstone games at the Stormwind Harbor. Come join in the celebration!", objectives = "Speak with M.C. Farala in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79189] = { id = 79189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Hearthstone's Anniversary!", description = "\"Hearthstone's been played for ten years, can you believe it?\n\nFarala, Master of Ceremonies, is hosting Hearthstone games in Durotar, between Orgrimmar and the docks. Come join in the celebration!", sourceObjective = "Speak with M.C. Farala in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[79193] = { id = 79193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spinning Spore Spines", description = "Orsenth sent you? And we are supposedly fused? Why... so I am wearing a medallion. But I have no memory... Well, no time for that.\n\nDid you see the spinning spores on your way here? I need the spines that they grow for... I need them for... now what was it again? Oh yes! There is no better instrument for carving out the fine detail that my work as a gem carver requires than those spines. Will you collect some?\n\nI will make my way back to the refinery. I am eager to get back and meet this Orsenth.", progress = "Why, what is this now? You're a stranger to these depths, are you not? What are you doing here?\n\n<You remind him of all you've spoken of.>\n\nWell, what are you waiting for? Go and get me those spines!", completion = "Where did you come from? Who are you?\n\nI do not know how you knew I needed these spines, but I thank you. There is no better instrument for carving out the fine detail that my work as a gem carver requires. I am a gem carver, you see!\n\nHave you met my new friend Orsenth? What- what was I saying?", objectives = "Collect 150 Spore Spines for Munderut.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79194] = { id = 79194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Source", description = "Orsenth told me you have been instrumental in dealing with the elemental problem here at the mine. I am Keldaz, supervisor for the militia. We came as soon as word of the attack reached us in Gundargaz. The miners you rescued said that the elementals poured out of the northeast mine shaft. \n\nI will leave some of my guards here to lend their support and have sent for reinforcements. If you are still willing to help, meet me outside the cave and let us see what we can do to staunch the flow of elementals.", completion = "Ah, {name}, you made it. We did as well, but were attacked often on our way over. Unfortunately, Nanthaz took a heavy blow and needs time to recover.", objectives = "Meet Keldaz outside of the northeastern mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79196] = { id = 79196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with The Severed Threads", description = "The Weaver has been keeping an eye on you. She has determined you would be a better asset with more resources at your disposal.\n\nCome to the Weaver's Lair. I have a parcel waiting for you.", completion = "For services rendered and services yet to be rendered, accept this with The Weaver's compliments.", objectives = "Speak with Lady Vinazian in the Weaver's Lair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79197] = { id = 79197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surface Bound", description = "{name}, the moment is upon us. We must make haste to the city of Dornogal, where our allies await. \n\nOnly together do we stand a chance against Harbinger's machinations.", completion = "I am glad to see you all back safely from your journey.", objectives = "Meet with Moira Thaurissan and your allies in Dornogal in the Isle of Dorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79199] = { id = 79199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with Keg Leg's Crew", description = "Your deeds have not gone unnoticed, and you continue to show that you are a renowned explorer!\n\nReturn to the Dragonscale Basecamp as I have prepared more supplies to help you continue in your endeavours.", sourceObjective = "Speak with Cataloger Jakes at the Dragonscale Basecamp.", sourceObjectiveStatus = "unverified-source-field" }
quests[79200] = { id = 79200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who am I?", description = "It's good to see you're awake. I know you must have many questions and we are here to answer them. I am Dawn, and this is Foreman Uzjax.\n\nMany things have changed since your last slumber began, including our Awakening Protocol. We are both here to guide you through it.\n\nLike many other newly awakened, you have heard a distant yet powerful song thrumming within you. A radiant surge of change. \n\nEmbrace it.", completion = "I want to reassure you. You are not flawed.\n\nThis protocol was designed to detect 'anomalies' within the {race}. Anomalies such as that surge you felt.\n\nBut they are not anomalies. Not anymore.", objectives = "Complete the first stage in the Awakening Protocol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79201] = { id = 79201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Analysis Interface", description = "This is the Analysis Interface. \n\nIn order to ensure our primary programming remained intact, these consoles were installed with a series of inquiries to assess the memory matrix of the newly awakened. \n\nAlthough Dawn will encourage you to answer in any way that you please--I... well, I hope you'll answer truthfully.\n\nProceed when ready.", completion = "Who you were, who you are and who do you want to be? \n\nAll questions every {race} from now on will be allowed to ask.\n\nOur fate and our purpose is ours to choose.", objectives = "Complete the Analyzing Sequence in the Analysis Interface.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79202] = { id = 79202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rock Beats Rock", description = "Welcome to the Procedural Forum.\n\nForeman Uzjax informs me that this chamber once served as our assignment testing facility. \n\nWith his guidance, we've repurposed this chamber.\n\nEarthen are not combat trained by design, so this room serves to prepare newly awakened earthen for the challenges of the unexplored world that lies ahead.", progress = "Whether they were once Storm Riders or Peacekeepers or craftsman and laborers, martial prowess takes time to hone and refine.", completion = "Combat doesn't come naturally to most {race} and yet again, you exceed expectations.\n\nYour training is exceptionally well-timed. It would seem we have an unexpected obstacle that lies ahead. \n\nSpeaker Kuldas can explain further.", objectives = "Spar with 6 newly Awakened Earthen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79203] = { id = 79203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Authorization: Negated", description = "The Bulwark of Authorization! That's what this chamber was once called.\n\nI had been working tirelessly to reconfigure it to its original state, when suddenly the whole blasted chamber started rumbling. \n\nA golem manifested out of nowhere and started attacking my machinists! We managed to escape, but the Golem locked down the chambers.\n\nDawn seems to think you've got what it takes to deal with it. Up to the challenge?", completion = "I've seen that room come to life more times than I care to admit, {name}. But that was something else entirely! \n\nI can't help but wonder where that golem came from. It certainly wasn't of {race} make.\n\nJust when I thought I knew everything about this old place, it throws another tool in the cogs.\n\nWell, back to work!", objectives = "Defeat the Phalanx of Authorization within the Bulwark of Authorization.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79204] = { id = 79204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whoever You Want to Be", description = "After an awakening protocol like that, I can see why Dawn says you're special.\n\nThe world is not prepared for an earthen like you. \n\n<Kuldas claps you on the back with a gravely chuckle.>\n\nDawn and the Foreman are waiting for you in the Awakening Vestibule.\n\nGo on, then! \n\nComplete your Awakening Protocol and get out of here!", completion = "Upon completion of their Awakening Protocol, {race} would leave these halls and venture into the Ringing Deeps and beyond to their assigned jurisdiction.\n\nTheir purpose was chosen for them. But not anymore.\n\nThe fate of our people is for us and us alone to decide.\n\nWhat you do and where you go is up to you.", objectives = "Speak with Dawn to complete your Awakening Protocol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79205] = { id = 79205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Waste, Not Want", description = "Everything have use, friend. Even things stoneheads throw away and think worthless.\n\nKobolds know better.\n\nGo and see what you can find. Need to scavenge lots of scrap. Enough for kobold crafting of new homes!", progress = "You will be surprised. Kobold crafting is amazing!", completion = "Not bad for |5human. We make good use of this.\n\nMost of it, anyway. Sometimes, one person's trash is really just trash.", objectives = "Collect potentially useful scrap from around the Warrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79206] = { id = 79206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Memories", description = "Something about this particular gemstone feels important. Perhaps it would be worthwhile to bring it to Speaker Brinthe.", completion = "Earthen use these gems to hold memories we would otherwise lose to the unrelenting march of time.\n\nWhen an earthen goes into stasis, we sometimes use a memory gem to witness their final moments.\n\nDuring our lives, we use them to carry our precious memories to the Archive, where they can be stored. Then we recharge our bodies and renew our minds in the Awakening Machine.\n\nThank you for returning this, {name}. Even shattered and faded, it's still precious.", objectives = "Bring the Faded Memory Gem to Brinthe.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79213] = { id = 79213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Anachronism", description = "Insert the batteries into the cylindrical holes on the console.\n\nThen, titans willing, we will see what it holds.", progress = "To obtain the power necessary, find an elemental of sufficient size to charge the artifact.\n\nIf I am right, the titan artifact will do the rest.", completion = "Curious. It is emitting a signal I have seen before.\n\nI have an idea where this may lead us.", objectives = "Activate the Excavated Console and use the device to defeat the Sargassum Guardian in Golgrin's Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79216] = { id = 79216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Web of Manipulation", description = "This town has been under siege, overrun by spiders! Even when we clear them out, they always return.\n\nSomething is behind these attacks!\n\nA small ledge northeast of Light's Bloom harbors these spiders. Scout out the ledge. Find out what is driving these spiders to attack us, and put an end to it!", progress = "Have you solved our spider problem?", completion = "Excellent work, {name}.  Now let us see if that puts an end to this eight-legged invasion!", objectives = "Explore the nearby ledge and deal with any threats within.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79217] = { id = 79217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Base", description = "Getting this factory up and running will be a challenge, but I think we'll figure out something. Let's head back to Gundargaz and consult with a friend of ours.\n\nHis mind will be a big help to us here.", completion = "Are you ready to put our heads together and come up with a plan?", objectives = "Meet Brinthe back in Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79218] = { id = 79218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Hallowfall Arathi", description = "Your labors on behalf of our people have not gone unnoticed. Nor will they go unrewarded.\n\nFind me in Mereldar.", completion = "Supplies run thin, but in your hands these goods will benefit all Algari. May the Sacred Flame light your path.", objectives = "Speak with Auralia Steelstrike in Mereldar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79219] = { id = 79219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Council of Dornogal", description = "The Council continues to be in your debt, friend.\n\nIf you visit me in Dornogal, I will give you supplies to reduce that debt.", completion = "Dispensing rewards. Thank you, champion. This should be sufficient remuneration for your efforts.", objectives = "Speak with Auditor Balwurz in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79220] = { id = 79220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Assembly of the Deeps", description = "Good work deserves good reward, yes?\n\nAssembly is grateful. Waxmonger Squick is grateful. Show gratefulness with many supplies.\n\nCome see Waxmonger Squick in Gundargaz.", completion = "For you! Take!", objectives = "Speak with Waxmonger Squick in Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79221] = { id = 79221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unusual Bug", description = "Nerubians in Rak-Ush may find this strange little spider of interest.", completion = "Oh, I was wondering where those had gone, thank you for returning it!", objectives = "Deliver this Unusual Bug to Widow Arak'nai in Rak-Ush.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79222] = { id = 79222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow-Hardened Mainspring", description = "<Maybe it was the effects of prolonged darkness or tinkering by Ezgi Irongear, but the strength of this spring would be of interest to Speaker Kuldas in Gundargaz.>", completion = "Most excellent find, this will require significant examination!", objectives = "Deliver this item to Kuldas in Gundargaz.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79223] = { id = 79223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finally, An Archivist!", description = "So you've got your bearings now? You've felt the dirt? You've smelled the history?\n\nWhy not celebrate this glorious moment of above average success with... a cap!\n\nThat's right! Take this token to our beloved provisioner, Aristta. She'll be happy to provide you with one of our all-purpose caps to signify your elevation to Archivist from naive passerby.", progress = "The cap suits you quite well!", completion = "Regardless of any assessment of your current aptitude, at least one could say that you look the part!\n\nNow then, your talents have been requested again by my colleagues. Better not tarry!", objectives = "Purchase an Archivist's Buckled Cap from Provisioner Aristta.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79224] = { id = 79224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering Intel", description = "The Widow Arak'nai sent word via one of those \"weave-rats\" of hers. She has a lead that may be relevant to our cause, and has invited us to investigate. All the training in the world is useless without knowledge of our enemy.\n\nMy own reconnaissance efforts in Azj-Kahet were met with... mixed results, as you may recall. I admit I am not keen on venturing down there again so soon. Fortunately, reinforcements have arrived with a capable spymaster.\n\nUnfortunately, she is... well. You'll see.", completion = "As I was telling your surly little spymaster, I expect this to be a mutually beneficial undertaking.\n\nWe shall both walk out of it with the information we need.", objectives = "Speak with Widow Arak'nai at the Weaver's Lair in Azj-Kahet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79225] = { id = 79225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Flame", description = "<A tinderbox of a Hallowfall Expedition member, its return would help honor the memory of those who bravely gave their lives.>\n\nAn expedition scout might possess knowledge about this item.>", completion = "On the Day of Shadows, Augustine panicked and broke ranks.\n\nThere were rumors he had left Hallowfall and found a way to the surface. I see he failed.", objectives = "Deliver the Expedition Tinderbox to Keyrra Flamestonge at the Shadowgrove Vineyards.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79226] = { id = 79226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Big Dig: Traitor's Rest", description = "Don your cap, put on a pair of sturdy gloves, and grab a snack because Traitor's Rest is ready for Archivists everywhere to sink their history-craving teeth into!", progress = "Not every day you unearth ancient dragon mysteries... or even a dragon themselves!", completion = "<Eadweard rustles through his unending robe pockets.>\n\nHere you are, Archivist {name}! Take this to Provisioner Aristta for your compensation.\n\nMay I suggest a new set of clothes, as your current set is... quite soiled.", objectives = "Aid Eadweard Dalyngrigge and the Azerothian Archivists at The Big Dig in Traitor's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79227] = { id = 79227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spider's-Eye View", description = "I have eyes in every crevice of the city save for one that has... eluded me.\n\nThe Transformatory is the grounds of Ansurek's most precocious minions and treasured pets. It is where the Ascension process was developed. I've only gotten my claws on it recently, thanks to dear Y'tekhi. Much of it remains uncomfortably shrouded.\n\nA more legs-on approach is in order. Place shadecasters to collect intel from my scouts, then meet Y'tekhi and your own spymaster Voss in a discreet corner of the district.", completion = "I don't like the sound of those reports. Looks like whatever they're cooking is coming to a head, right in time for us to walk in.\n\nDon't worry. I'll let you know if we get in too deep.", objectives = "Place shadecasters to rendezvous with the Weaver's scouts in the Umbral Bazaar, the Eastern Span, and the Twitching Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79230] = { id = 79230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creeping Through Corridors", description = "I've identified three sites of interest to investigate. \n\nA stockpile on the east side of the complex, a warehouse in the center, and lastly, that big storehouse with royal Sureki flags outside it. We'll rendezvous there.\n\nThere's less chance of discovery if we move separately through the area. You may be hidden from most nerubians, but the Ascended will sniff you out. Chuck some of these anger pheromones at them if you get heat, it'll distract them.\n\nStay sharp, stay quiet.", progress = "Don't let your guard down. Not here.", completion = "We came down here to figure out what these nerubians were up to. I don't think I like the answer.", objectives = "Investigate the western stockpile, central warehouse, and royal stores of the Transformatory, using anger pheromones to distract guards and avoid detection.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79231] = { id = 79231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Headquarters! Again!", description = "You've done truly incredible work! The proof is obvious: you are, in fact, a proper Azerothian Archivist.\n\nMeet us all back at our headquarters in Thaldraszus. Eadweard would like codify all your helpful labors and achievements for our group.", completion = "Excellent work, {name}! Most excellent work!\n\nI can see that I was right in bringing you aboard. You have a true archivist's spirit!", objectives = "Meet with Eadweard Dalyngrigge at the Algeth'ar Academy in Thaldraszus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79232] = { id = 79232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those Who Fell", description = "Since the Day of Shadows these lands have been a dangerous place. \n\nThe kobyss are emboldened, the nerubians probe our lands, creatures of pure shadow have begun to manifest themselves.\n\nThe memory of those who have fallen is etched in our everyday lives. We must locate their remains to bring closure. \n\nSearch for the Tinderboxes of these missing expedition members and return them to me.", progress = "Have you located the tinderboxes?", completion = "These tinderboxes are but a small symbol of the immense loss we suffered on the Day of Shadows. We will recover the bodies you have located and begin to heal the memories of our loved ones.", objectives = "Locate the remains of Oskaer Daleclash, Dalian Ironlink, and Idona Seerstone, and recover their tinderboxes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79233] = { id = 79233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lab Access", description = "As much as I adore skulking in the shadows, the juiciest intel is going to be inside the laboratory of the Grand Splicer.\n\nOf course you'll need the proper pheromones once you're in, but we can take care of that with a little biological forgery.\n\nThe nerubian loyalists here are surely on the invite list. Six of their secretions should be enough to disguise the three of us.", progress = "If you saw me? No you didn't.", completion = "Finally! I was waiting for when we'd stumble upon the real intrigue.", objectives = "Collect 6 Loyalist Secretions from nerubian loyalists in the Transformatory area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79234] = { id = 79234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Small Bag of Seeds", description = "<This small bag of seeds seems forgotten, perhaps Aliya Hillhelm could make use of them.>", completion = "Why thank you!", objectives = "Deliver this small bag of seeds to Aliya Hillhelm at the Hillhelm Stead.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79237] = { id = 79237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making of a Monster", description = "We've got a new objective: Figure out what Ansurek's plans are for this... thing.\n\nWe'll find our answers inside the laboratory of the Grand Splicer. I'd bet my blades on it.\n\nI scouted a maintenance hatch on the roof that you can grapple up to. Y'tekhi brewed up some weird concoction that they claim will get us the proper clearance once inside. Yuck.\n\nMeet you in there.", progress = "I don't like this. There's something we're still missing here.", completion = "That... wasn't what I expected to find out. \n\n<Lilian clears her throat.>\n\nFamily drama aside, whatever the old queen used to be, she'll be a big problem for us when she inevitably shows up on the battlefield.", objectives = "Access the Laboratory of the Grand Splicer via roof hatch, then investigate clues as to the purpose of the First Ascended.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79239] = { id = 79239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Queen's Chains", description = "Ansurek... that worm, that witless, gutless little--\n\n<Y'tekhi growls under their breath, struggling to maintain their composure.>\n\nIf this is what's become of Neferess, we must free her. She is still our queen. My mistress will know what to do.\n\nWhen the Weaver discovers what they've all done, there will not be a crevice deep enough to escape her wrath.", completion = "Remember when I said I'd let you know when we're in over our heads? This is it.", objectives = "Destroy Neferess's shackles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79240] = { id = 79240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rogue Agent", description = "We lost Y'tekhi.\n\nWe can worry about the how of it later. Right now, we need to worry about taking them down before they make things worse.\n\n<Lilian snorts.>\n\nI guess we came down here to find out what Xal'atath had up her sleeve. ...I wish we'd minded our own business.", progress = "Hard to think of how this could have gone any worse.", completion = "We're out of the public eye, for a moment.\n\nGetting Y'tekhi back to the Weaver is my priority. Yours is dealing with the weapons.", objectives = "Subdue Y'tekhi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79241] = { id = 79241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go Loud", description = "So much for keeping this operation quiet. At least now that our cover's blown, we can really mess things up.\n\nThey're hauling weapons across the south bridge. If we turn those weapons against them, they'll have to resupply their whole army. That'll buy us time, at least.\n\nI've identified six weak spots across the convoy. Rig up bombs to all six, then get out of there and watch the fireworks.", progress = "They know we're here. May as well make the most of it.", completion = "Not only is the convoy in shambles, but we were able to slip away in the chaos. If there's one thing you're good at, it's making noise.\n\nStaying quiet? Eh, we can work on it.", objectives = "Plant 6 Commandeered Nerubian Charges at specified points across the convoy, then remotely detonate them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79243] = { id = 79243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manufactured Mutiny", description = "We don't have the firepower to dismantle their whole manufacturing operation, but what we do have is two leftover vials of anger pheromones. Let's make them count.\n\nThere's a siege marshal and a quartermaster overseeing the preparations and giving everyone orders. Logistics types, but they still pack a punch. That's where those pheromones come in.\n\nHit them with a vial, and their own armies will turn against them. Take out both, and we watch the operation crumble.", progress = "Those aggression pheromones came in handy... let's make sure not to waste them.", completion = "It's only a delay, not a hard stop, but it's still a big one. It'll give the folks up top more time to prepare.", objectives = "Slay Siege Marshal Tekhzok and Royal Quartermaster Ze'erik.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79244] = { id = 79244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News From Below", description = "I could hear the explosions from here. That'll buy us some time. Maybe I'd even be relieved, if this had gone less poorly.\n\nY'tekhi is secured in the back, where they can't overhear anything. Whatever Xal'atath did... it hasn't worn off yet. The Weaver has people looking into it, but the outlook is grim.\n\nAlleria is going to want a status report. Good luck.", progress = "Nothing to do but keep going.", completion = "At the end of the day, we delayed their advance and got some good, actionable intel that everyone up here can work towards.\n\nWas it worth it? Time will tell.", objectives = "Inform Widow Arak'nai about what was found in the Transformatory. Then, return to Alleria at Dornogal on the Isle of Dorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79246] = { id = 79246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain's Orders: Coffer Collector" }
quests[79249] = { id = 79249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain's Orders: Kill Haul" }
quests[79254] = { id = 79254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everspout" }
quests[79256] = { id = 79256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hint of Fear", description = "My father thinks that while he and Dagran were dealing with the skardyn tae the south, he caught a sensation o' his old hammer, Fearbreaker.\n\nHe said it slipped out o' his fingers when Dalaran crashed, and it's been bothering him mightily. That hammer belongs tae the Bronzebeard clan, and has for generations. But he hasn't been himself lately, either.\n\nI'm willing tae have a look, so he doesn't worry that he might've missed it. Meet me down at Camp Murroch, and we'll have a quick look around.", completion = "Well...\n\nI wasn't expecting to actually see Fearbreaker here.\n\nIt's really here, but it ain't exactly within easy reach.", objectives = "Meet Moira Thaurissan outside Camp Murroch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79257] = { id = 79257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grotto Grievances" }
quests[79258] = { id = 79258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mineral Water Woes", description = "When that magic hammer fell into the Deeps, I knew it could be a formidable weapon against the skardyn menace. Your friend has told me that it's 'particular' about its wielder.\n\nFortunately, I am a hero!\n\nAnd as a hero, I know how to get close to it. We need to have a good mix of pollen and water plastered onto us. That way, the beast standing over it will think we're just like it.\n\nThat mineral water has to be the exact right temperature to mix with the lashroom dust and blend in.", completion = "That was a right pain. But we got the water Berrund asked for.\n\nIt's time we get a move on. I don't want my father's hammer to just languish there in the mud. That doesn't sit right with me, not at all.", objectives = "Acquire the proper-temperature mineral water from the Living Grotto springs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79259] = { id = 79259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put On a Good Face", description = "Berrund here says that the massive beast standing over Fearbreaker is very particular about what kinds of creatures it allows near it.\n\nIf we blend in, he says, we can get close enough tae nab the hammer. But tae blend in, he says we have tae get covered by the dust an' pollen in the grotto. \n\nThose Lashrooms look like they're a good place to start. \n\nIt all seems suspicious tae me, but fer now, we'll play along until I can recover Fearbreaker and bring it back to my father.", progress = "Have you gathered up that dust? It's the only way you're going to get near that hammer, especially with that creature wandering around.", completion = "<Berrund the Gleaming appears not to have a speck of pollen on himself.>\n\nYou got yourself good and covered in that lashroom dust, all right.\n\nI'm a bit surprised you're not itching and sneezing, like your friend here.", objectives = "Collect Lashroom Dust from Lashrooms in the Living Grotto.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79260] = { id = 79260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epicenter", description = "There is the creature standing between us and that magic hammer. It certainly made an impact when it landed here in the Ringing Deeps, didn't it? Look at the size of that crater!\n\nWith the pollen and water splashed on you like this, you should be able to approach that beast and, theoretically, not be harmed. You'll blend right in with it!\n\nBut if it does turn aggressive, don't worry, I'll be right behind you.\n\nWe'll get that hammer out of here safely!", completion = "Why that amber-sucking, slime-spined, travesty of an earthen! I've met troggs with more honor!\n\nHe took Fearbreaker! He took my family's hammer and left us to die to that creature!\n\nThis cannot stand. I will not allow such disrespect to you... or to me.", objectives = "Approach the Verdant Hulk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79261] = { id = 79261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boiling Mad", description = "That gravel-brained ingrate! He took Fearbreaker and ran off to the north!\n\nIt's not that I want that hammer for myself. I don't. But it belongs to the Bronzebeard clan. It should be in the hands of someone who respects its power!\n\nWe need to track him down before he hurts himself or someone else with that hammer!", completion = "These earthen have had a bad time of it.\n\nBerrund's already run headlong into there, but if he was hoping to clean up the ills of the place, he's clearly in over his rocky head.\n\n<Moira points to the nearby rocky contusion>\n\nLook, he can barely keep hold o' Fearbreaker! What if he drops it and is killed? We need tae find him.", objectives = "Track Berrund and Fearbreaker through the Ringing Deeps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79262] = { id = 79262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clean Up House", description = "It looks like the destruction around the Coreway rattled loose more than just a few stones down here. It's stirred up all sorts o' dark things.\n\nIf this was a thriving mining operation, it ain't anymore. \n\nWe need to help the earthen get it under control again, and that means thinning out these beasts.", progress = "I want to get Fearbreaker back, but we need to clear out some of these agitated beasts first.", completion = "That's a mite better. At least there won't be so many of those creatures running amok around this area.\n\nNow we've got other problems.\n\nWe've got skardyn.", objectives = "Slay agitated creatures in the Rumbling Wastes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79263] = { id = 79263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fault Lines", description = "Berrund took Fearbreaker for himself. I suppose he thought he could save these people. Be the hero.\n\nBut ye can't go about doing the wrong thing for the right reasons.  I know from experience. If a rock is hollow tae begin with, it never can be solid again, no matter how hard ye try. \n\nHe's likely tae need saving himself now. Let's find him in this blasted place.", progress = "You found me?", completion = "<Berrund the Gleaming's skin is chipped and damaged. His eyes can barely focus. He is near to death.>\n\nEvery time... I tried to use the hammer... it just got away from me. I could have saved people. I don't... I don't...", objectives = "Find Berrund the Gleaming within the Rumbling Wastes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79264] = { id = 79264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "These Strong Hands", description = "<Berrund the Gleaming coughs dustily.>\n\nI knew I couldn't take the skardyn without some help. I thought, if I just had that magic hammer, then nothing would stop me. I had to have it, you see, or else, maybe I wasn't who I was made to be.\n\nBut it kept slipping out of my fingers. Like it didn't want anything to do with me. It fell out of my hands at the worst moment and now... <He coughs again.>\n\nIt's clearly not mine. It never was. I'm... I'm... sorry.", completion = "I thought this day would never come because my Da' would never have given me Fearbreaker. He probably would have wanted it to happen a different way.\n\nBut I have it now, and I'll make sure it gets back to him safe.\n\nFirst though, we have unfinished business here.", objectives = "Witness Moira Thaurissan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79265] = { id = 79265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fearbreaker", description = "The skardyn have taken over the operations here in the Rumbling Wastes. That's why Berrund thought he needed Fearbreaker.\n\nWe're going to finish that job before I take the hammer back to Magni.\n\nWhat kind of a queen would I be if I wasn't willing tae put myself in danger for the good of others? Let's get in there and save as many as we can.", completion = "We got there in a roundabout way, but we still made a difference in the lives of these earthen.\n\nBerrund, hopefully, has learned a lesson in real heroism. But I suppose we'll see in time.\n\nNow, let's get this over with.", objectives = "Slay skardyn and save earthen in the Rumbling Wastes with Moira Thaurissan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79266] = { id = 79266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bronzebeard Legacy", description = "Well, we did what we set out tae do... and more. We found Fearbreaker and did some good with it.\n\nNow it's time tae bring it back tae Magni.\n\nLet's hope Berrund learned a lesson here, but I suspect he'll manage tae get himself in trouble again soon. Hopefully, it'll be fer the right reasons an' with the right support.", completion = "It's funny. I can see why me Da' was so fond o' this hammer. And what it meant when he trusted others tae hold onto it.\n\nFearbreaker's got a mind of its own, in ways. It wants what it wants. \n\nI suppose I relate.", objectives = "Meet Moira Thaurissan in Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79267] = { id = 79267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wax On, Pot Off", description = "If candles are important to kobold society, I have an idea that might disrupt their production... or at least make sure there's an unpleasant surprise waiting for our enemy.\n\nTake that cinderbrew. Drop some in those large vats of wax the kobolds are prepping at the top of that hill. It's a powerful explosive. It burns aggressively, so try not to drop any.\n\nIt should certainly make any candles made with that wax quite feisty, once they're lit.", progress = "Try not to breathe too many of the fumes.", completion = "Hopefully, that takes them down a peg or two.\n\nA leader's power waxes and wanes. With all this destruction, the Candle King's power is waning.", objectives = "Sabotage the pots of wax in the Warrens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79268] = { id = 79268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gundrak Fast Track", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
