quests[79273] = { id = 79273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coldarra Climb - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79274] = { id = 79274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coldarra Climb - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79282] = { id = 79282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Debut", description = "The Proscenium is looking amazing! Are you ready to get on stage?\n\nGive us a hand as part of the crew, and we'll give you a chance to act.\n\nWill you accept this directive?", progress = "I haven't seen you on stage yet, {name}. You won't win any fans by standing around!", completion = "What a good show! I think your work on the Proscenium has made this an excellent stage.\n\nCome by again sometime. We always need hands for the cast and crew!", objectives = "Complete one Theater Troupe event in The Proscenium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79295] = { id = 79295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hose 'Em Down - Activate" }
quests[79297] = { id = 79297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightwatch", description = "Xal'atath is using the Order of Night to serve her whims.\n\nI overheard some of the Arathi complaining about a new wave of propaganda that has been put up around Mereldar. Find what you can and deliver it to General Steelstrike. I'll be there as soon as I can.\n\nWe need to convince her of the severity of this threat.", progress = "Anything I can help you with, {name}?", completion = "<General Steelstrike reads through the propaganda you brought her.>\n\nI need to know more about this Xal'atath.", objectives = "Collect 8 Order of Night Propaganda.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79300] = { id = 79300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Notebook", completion = "Edwyn took it? Of course. \n\nHe desperately wants to be selected as captain, but he knows I'm ahead in the rankings. His only chance is if I can't turn in my report. We have to get it back!", objectives = "Help Sophietta look for her notebook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79301] = { id = 79301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Height Club", description = "I'm so tired of Edwyn. From the day we all arrived, he's been telling everyone he'll be selected as captain.\n\nHe's a great flyer--very talented, and he knows his stuff. But his ego gets in the way of treating people as he should. And he knows my grades and flight review scores are higher.\n\nBut if I can't turn in my report, he'll be the next captain. Take it back from him!", progress = "Did you get it back? I'd love to see the look on Edwyn's face...", completion = "He threw it into the valley and the WIND TOOK IT?!", objectives = "Confront Edwyn about the notebook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79302] = { id = 79302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gone with the Wind", description = "I can't believe Edwyn threw my report out into the wind. \n\nCan you please track down what papers you can find? I'll look for any around the school grounds, you check the valley. \n\nThis report is already late... But I had some really good insights around airship capabilities. When Headmaster Fynch sees them, maybe he'll still allow me to turn it in.\n\nBring me whatever pages you find!", progress = "I hope you found all the pages, {name}!", completion = "I really wish this looked better. I'm honestly ashamed to turn it in, if Headmaster Fynch will even let me. \n\nBut we have to try--the ideas are what matters, and they're still true!", objectives = "Recover 10 pages from Sophietta's report.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79303] = { id = 79303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Principled Principal", description = "Great work gathering these up. I found a few blowing around up here, so I think we've got all the pages. Let's get this to Headmaster Fynch! He's probably in the classroom.\n\nI sure hope he accepts it. He says he doesn't accept late work, but there were a lot of extenuating circumstances at play here. And if he doesn't, I'll be reporting to Edwyn as my captain. I'm not sure I could do that, after what's happened.", completion = "Sophietta has been a phenomenal student. Honestly, I am too close to the situation to make that decision without bias. But it was too nuanced to reject without consideration.\n\nAs an outsider, I know your decision wasn't colored by months spent with these students, so I could trust your judgment. I appreciate your help in resolving the situation, {name}.", objectives = "Get Sophietta's report to Headmaster Fynch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79304] = { id = 79304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Care Package", description = "My cousin Sophietta and I came to Hallowfall together as stalwarts. Since arriving, we both lived here in Dunelle's Kindness for years. But she left last year to follow her dream of being one of our airship captains, or at least joining an airship crew.\n\nShe's a strong person, but I don't know how she's doing. Especially without Innkeeper Valrin's sweetrolls! She can't get them at Lightspark, the Sky Academy. Will you take these to her, and make sure she's doing alright?", progress = "What's this? Are these for me?", completion = "That was very kind of Barahl to send these. You can tell him I'm doing well, but first, do you think you could help me with something?", objectives = "Take the care package to Sophietta Lynflayme at Lightspark Sky Academy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79309] = { id = 79309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Status Report", description = "Airships give the Arathi Army command of the skies. But roads are the lifeblood of empires. My scouts protect and light the passageways of Hallowfall for our citizens.\n\nOne such patrol has been late to report their walk of the eastern road. Seek my missing scouts by the sight of smoke or flame. Arathi soldiers know better than to linger in the dark.", completion = "<Scout Wayshelm does not meet your gaze.>", objectives = "Locate the missing Arathi Army scouting party.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79310] = { id = 79310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek the Lost", description = "Guard our ways, repel the dark. Civilize this twisted land. All in the name of our empire. This is the mission of the Arathi Army. A mission I can heed no longer.\n\nI am afraid.\n\nI won't go back into the dark. Not after what I've seen. If Maevest or any of my other companions survived, they must crave the mercy of a swift death. And I left them to that terror.\n\nTell Captain Trueflame her scouts died in darkness, one and all.", progress = "<Scout Wayshelm gazes into the flames of his campfire.>", completion = "<Scout Wayshelm clutches the compass tight and finally raises his gaze to regard you.>", objectives = "Look for a member of Wayshelm's party.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79311] = { id = 79311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stem the Flow", description = "The roads were meant to be lit. But the path was overgrown, the lanterns dark. Swarming, frothing, and reeking with rot. It all happened so fast. By the time we realized the danger, the beasts were upon us. The largest of them was huge and black as night.\n\nIt is our duty to slay monsters and push back the darkness. But the thought of going back fills with me fear. \n\nI've lost my nerve. But you, outsider, can still make this right.", progress = "<Scout Maevest's compass gleams in the firelight. Wayshelm has bound it with twine and now wears it around his neck.>", completion = "You're alive. Praise the Sacred Flame.", objectives = "Slay 12 Bloatrot Stingers or Fungal Infestors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79312] = { id = 79312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mow the Masses", description = "Maevest and I broke away from the others and fled, their screams left in our wake. Foul muck smothered our lanterns and we stumbled in the dark through knee-high waters. I heard a splash like she had tripped and fallen in, but I couldn't bring myself to look back.\n\nOnly later did I find the tiny bite marks on my ankles. Be warned, there's something in the water.\n\nI took notice of fronds growing from the pools. Swarming insects feast on their sickly nectar. Destroy those plants and starve the beasts.", completion = "<Scout Wayshelm gives you an approving nod and finds a grim smile.>\n\nIn the dark, even the plants want us dead.", objectives = "Cut down 8 Foulnectar Fronds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79313] = { id = 79313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Grows in the Dark", description = "We are told never to walk in the darkness. To carry light wherever we go. The thought of returning this way filled me with dread. \n\nBut your courage shines with splendor, {name}. At your side, my way is lit.\n\nNo more hiding. The beast clad in black chitin, the one that killed my friends, dies in that cave. I am with you.", completion = "Wayshelm told me everything.\n\nA debt of gratitude is owed. To you, and to the scouts who gave their life for our empire.", objectives = "Slay Fallowbarb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79315] = { id = 79315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Harlbrand" }
quests[79316] = { id = 79316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfunctioning Harvester" }
quests[79317] = { id = 79317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morkus Grimlock" }
quests[79318] = { id = 79318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narla Thunderhoof" }
quests[79319] = { id = 79319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frenzied Owlbeast" }
quests[79320] = { id = 79320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorthak Grimtusk" }
quests[79321] = { id = 79321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Catalyst's Gift", completion = "Every other week, the catalyst will grant you enough power to imbue one piece of equipment.\n\nKeeper Tyr must be watching us. Wherever he is, this is no coincidence.", objectives = "Speak to Antuka in Tyrhold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79322] = { id = 79322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What the Duck?", description = "What the--why are all these ducks here? Something has them agitated. They almost knocked over my beautiful golden egg heirloom!\n\nWe need to clear out these chaotic quackers so we can continue our festivities. I'll keep them from entering the inn, but can you help clear out the rest?", progress = "Show those ducks who's boss!", completion = "Those ducks sure made a mess of things. Thanks, {name}.", objectives = "Scare off 10 ducks using the Horn of Honking.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79323] = { id = 79323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fowl Concoction", description = "We need to put an end to this duck invasion.\n\nWhile I was shooing some stragglers away from the inn, a flock showed up and made off with some of our decorations and eggs. My precious heirloom was among the items stolen!\n\nPlease, {name}. I won't stand for these pilfering poultry. I know a mage in Stormwind who might have some ideas on how to handle this.", progress = "Have you spoken with Emmery yet?", completion = "Don't worry, I'm sure he'll have a good solution. Wait here, I think I see a portal forming.", objectives = "Speak with Emmery Fiske at the Wizard's Sanctum in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79324] = { id = 79324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Waterworks", description = "Getting the Waterworks up and running is our first objective. Nothing else we do matters if we can't get power to the facility.\n\nMeet up with Dagran and ZZ-01-47 once you get there. And try to keep them on the sidelines. I don't want to explain to Moira that her son was injured, or worse, under my care.", completion = "This place is a mess! I think Zee-Zee and I will stay up here where it's dry.", objectives = "Meet up with Dagran and ZZ-01-47 at the Waterworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79325] = { id = 79325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowvein Extraction", description = "I sent Zee-Zee ahead to the Shadowvein extraction site.\n\nFrom what they transmitted back it looks like the area is swarming with rock worms and covered in this... discharge. I gave them an upgrade while we were waiting for you.\n\nI don't know how effective it'll be in battle but the results should be shocking for anyone that tries to threaten them.", completion = "<Zee-Zee beeps in recognition and excitement. It seems like they're ready to get underway.>", objectives = "Meet up with ZZ-01-47 at the Shadowvein Extraction Site.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79327] = { id = 79327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Glittering Shard", description = "<Glistening with an inner light, this shard of crystal feels warm to the touch..\n\nOrsenth may be interested in examining this piece of ore.>", completion = "A crystal shard? From a glittering cave? Why does that sound familiar to me?\n\n<She takes the crystal in her hands to examines more closely.>\n\nThis can't be! It's the healing crystal I mentioned earlier! We thought it was lost. What a wonder to hold it in my hands...\n\n<She sighs deeply, looking at Munderut.>\n\nI wish it could mend our minds as well as it mends our wounds. We need to get the vault back up and running.", objectives = "Bring the glistening clay to Orsenth near Nibelgaz Mine.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79328] = { id = 79328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Embassies and Envoys", description = "I feared what we would find when we returned here, but I am proud to see that though we were forced to leave, you were able to forge a friendship with the earthen and stand against the nerubians.\n\nWith your strength, we will win this. But first we need a plan, and for that we need space here in Dornogal for discussion.", completion = "Ye mean tae tell me ye have been an interior decorator this whole time an ye have been holdin' out on me?\n\nWell done, {name}.\n\nYe are rearrangin' me chambers when we get home, ye are.", objectives = "Set up your faction's embassy in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79329] = { id = 79329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glowing Harvest" }
quests[79330] = { id = 79330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duck Tales", description = "Take this potion, {name}. You should be able to communicate with your feathery friends with it.\n\nBut don't blame me for any unintended side effects you may experience.", progress = "Go on now, have a chat with those ducks!", completion = "What? Some of the ducks are druids?\n\nThey won't get away with their interference.", objectives = "Use the potion to get information from 5 ducks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79331] = { id = 79331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just a Waddle Away", description = "We need to find out where those ducks are hiding our stolen goods! And who this mysterious Daetan is, while we're at it.\n\nI convinced Emmery to give me more of that potion. Take it and find my heirloom!", progress = "Where would those ducks be hiding...", completion = "<Zinnia carefully examines the heirloom>\n\nDid a duck gnaw on this? This is going to take some elbow grease to polish out!\n\nThank you for your help, {name}.", objectives = "Discover the duck's hiding spot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79333] = { id = 79333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fleet Arrives", description = "From the moment we crashed on this isle, it were clear as crystal we'd be needin' allies if we hoped to face Xal'atath. \n\nJaina and Thrall took off tae muster reinforcements, an' you and I set tae work seein' what could be done here with the earthen.\n\nAn' I have to say we've done well on our own, haven't we? \n\n<Moira smiles at you proudly.>\n\nBut it looks like our reinforcements may have finally arrived. Peacekeepers spied ships comin' this way. Go take a look an' confirm the good news!", completion = "I'm glad to see you are well, {name}.\n\nThe journey took longer than anticipated. The capricious sea had its own plans it seems.", objectives = "Scout the harbor for ships arriving from the Horde and Alliance fleet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79335] = { id = 79335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One More Tradition", description = "Before I shut down, I must craft an item that is meaningful to me. \n\nAs a Stonebound, I worked the mines. I had a lantern I made and used until I lost it in a collapse. I became Unbound shortly after.\n\nI wish to forge a new lantern to guide my way through these final moments.\n\nThe lantern was made of an ore found in small amounts around this area. I used a charged core in the lantern. You can find them in the stormfangs that roam these hills.\n\nGather the materials, and I will forge the lantern.", progress = "Have you gotten the materials I asked for?", completion = "These will do nicely!\n\nNow... hopefully I can remember how to forge a lantern.", objectives = "Gather 5 ore and 5 Charged Cores near Fallside Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79336] = { id = 79336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forging of Memories", description = "Before its shutdown, we earthen would descend to the Awakening Machine below and renew our cycle. But now, even if it was still working, I would see my cycle broken and be remembered as I am.\n\n<Korgran lets out a deep sigh.>\n\nThese hands look strong, but they become heavier with each passing moment. The stiffness in my wrists and elbows will not let me carry the items to the forge.\n\nPlease, add the right material to the forge as I call them out.", progress = "Oh, I almost forget. I did ask you to help with forging the lantern, didn't I?", completion = "Is it... hm, It looks like... I can't remember.\n\nBut this lantern is absolutely magnificent!", objectives = "Help Korgran forge his lantern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79337] = { id = 79337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Journey", description = "This lantern is perfect.\n\nEnough of this. It is time! I can feel my memory clouding. We have to get going. Urtago is waiting for us. They will join us on my final journey to Mourning Rise, where we will conduct a ceremony.\n\n<Korgran forces a smile.>\n\nIt is nothing fancy, I promise. As I said, it is more symbolic than anything else.\n\nMy head feels heavy. What was I doing again? Hmm, oh, right! Meeting Urtago!", completion = "{name}, we have to find Korgran! If he keeps on exerting himself, he will shutdown in the middle of nowhere.\n\nAnd it's not safe for him to be out in his condition. He would be easy prey for stormfangs and even kobolds.", objectives = "Wait for Korgran and then regroup with Urtago outside at Fallside Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79338] = { id = 79338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Earthen", description = "This is horrible! I knew I should have been keeping a closer eye on him.\n\nConfusion is the last symptom before a shutdown. Our memory is finite and starts overwriting. The more an earthen exert themselves, the faster their energy depletes and they lose memories. Korgran must be scared not knowing where he is--maybe not even who he is.\n\nI am such a boulder head!\n\n{name}, please, I think I saw him go east into the trees. Meet me there up the road!", progress = "Were you able to find any sign of Korgran?", completion = "Oh no, Korgran's condition is sliding downhill fast.\n\nShowing him the lantern was a good idea.\n\nThank you for guiding him back to me.", objectives = "Help Urtago find Korgran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79339] = { id = 79339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Tradition", description = "An Unbound earthen can't return to the Coreway, so we have Mourning Rise. But looking at Korgran, remembering our last conversation before...\n\nI may not be the Mourning Rise caretaker just yet, but with Korgran's condition, it falls to me to be in charge. \n\nAs Unbound, we made our own rules and traditions. So what if he doesn't want to stand at Mourning Rise? If a seaside memorial is what Caretaker Korgran wants, that's what he gets.\n\n{name}, meet me at the shore to the southeast of here.", completion = "He enjoyed the walk, but it has taken a heavy toll on him.\n\nKorgran barely recognizes me now.", objectives = "Meet Urtago and Korgran by the shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79340] = { id = 79340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools of Declaration", description = "As Unbound caretakers, we have a tradition for when a master bequeaths their mantle to their apprentice. \n\nFiguratively, of course.\n\nTo do that, Korgran will need a horn.\n\nHe would then face me, blow the horn, and the sound signifies his passing the mantle of the Mourning Rise caretaker to me.\n\nI saw shalehorns to the west of here. I would be thankful if you could bring me several of their horns. I will choose one that is suitable.", progress = "Remember, the horns must be in pristine condition.", completion = "These are beautiful!\n\nI feel sorry for the shalehorns, but there are many of them around.", objectives = "Collect 4 Pristine Horns near Restless Estuary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79341] = { id = 79341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing Ashes", description = "The Unbound have a symbolic ceremony of cleansing. We perform it before a shutdown. \n\nIt is a symbolic process of purification. For it, we need to gather ashenfold, a flower that grows around the isle. We waft the smoke of the burned flowers through the fissures and cracks in our bodies to symbolically remove impurities.\n\nWe are then ready to embrace our final moments.\n\n<Urtago looks at Korgran with a hand on her chest. Her face falls.>", progress = "Do you have the flowers, {name}?", completion = "Thank you, {name}. I will prepare them for the ritual.", objectives = "Collect 6 ashenfold flowers near Restless Estuary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79342] = { id = 79342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "As He Departs", description = "It is time for the ceremony, {name}.\n\nPlease place the bowl of ashenfolds by Korgran and then hand him the horn.\n\nOnce the ceremony concludes, I will be the new caretaker. Then I will have to say a final farewell to my friend.\n\nKorgran will shutdown peacefully, knowing we were here by his side in the place he loved most--something I wish and hope to have when it is my time.\n\nMy core is mud, but it is a great honor to stand here with him... and with you.", progress = "It is a bittersweet moment.", completion = "What an honor it is to be here. To be present at such an event.\n\nYou were part of it, and I know that deep inside him, somewhere within Korgran's core, there will always be a living memory of you, {name}.\n\nThank you.", objectives = "Help Urtago and Korgran perform the ceremony.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79343] = { id = 79343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everyday I'm Snufflin'", description = "Perhaps the kobolds of Gundargaz would be interested in this Odd Glob of Wax.", progress = "You snuffle something good?", completion = "Middles always need more wax for project.\n\nTrade bigger, shinier ruby for if have lots. Get fancier things for helping.\n\nKeep snufflin'. Keep trading.", objectives = "Bring the Odd Glob of Wax to Gnawbles in Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79344] = { id = 79344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urban Odyssey", description = "Did ye hear, {name}?\n\nA lot of folks from the city are eager to lend a hand an' support our attack on the nerubians and Xal'atath. I think it's worth reachin' out tae them tae see how they could pitch in.\n\nThe more support we gather, the better.", progress = "I am glad to see you return, {name}.", completion = "Thank ye, {name}. The more people we get on board with helpin', the more successful we'll be.\n\nBut we won't get anywhere if we dunnae have a large enough fightin' force.\n\nThe earthen are nae in good shape. But I think Alleria may be helpin' with that.", objectives = "Ask around Dornogal for pledges of support in the coming conflict.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79346] = { id = 79346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chew On That", description = "Fishing out here is not easy, especially when the spooky sounds of the darkness start to wear on the nerves.\n\nI've taken to chewing on the Duskstem from the tall plants nearby. It's sweet and chewy, keeps the jaw busy, and helps me pass the time!\n\nIf you could lend a hand by gathering some Duskstem with your flying mount, I would be most appreciative.", progress = "Have you collected enough?", completion = "You made that look easy. It usually takes me an hour to climb one of those plants.", objectives = "Collect 20 Duskstem from the tallest plants that grow in the darkness.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79349] = { id = 79349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entrepreneur, Inc.", description = "Okay, color me impressed. You are officially my Coinchamp! It's like a champion, only I pay you to do things. A mercenary, only with better branding.\n\nYou should meet my business partner, Ripsnoodle. He's working out some deals with his own coinchamps with the niffin over at Mmarl. He might have more work for you--though I recommend not buying anything he tries to sell you.\n\nYou can find Mmarl east of here. Just follow your nose, you can smell it from a mile away.", completion = "Skedgit actually found something out there? She always did have a good nose for business.", objectives = "Find Ripsnoodle in Mmarl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79351] = { id = 79351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Level 25" }
quests[79352] = { id = 79352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Level 24" }
quests[79354] = { id = 79354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Machine Speakers", completion = "It is a new day in the Ringing Deeps.", objectives = "Watch the conversation between Moira and Speaker Brinthe in Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79355] = { id = 79355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prisoner Preservation", description = "The beasts took our people! Dragged them away when we were gettin' our first rest since our escape!\n\nWe only just escaped those nerubians. We can't afford ta lose more people.\n\nSearch Pillar-nest Vosh. It's where all those beasts came from. If we're lucky our people are still alive.", progress = "Survivin' ain't easy, but we gotta keep pushin' on.", completion = "You did all you could. I be in your debt. We be honorin' Jeti's memory by dealing with da nest.", objectives = "Find 4 Expedition Members.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79356] = { id = 79356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antifungal Firestarter", description = "Consider it a professional hunch, but those spores comin' out of those fungal pods and the ones afflictin' all da beasts are connected. \n\nMaybe if we destroy da fungal spore pods it'll slow whatever control those fungarians have on da beasts.\n\nTake these antifungal firebombs and torch as many fungal spore pods as you can!", progress = "Too many strange tings occur this far underground. Watch yourself.", completion = "Excellent work my friend. Dat will keep these beasts in check.", objectives = "Burn 8 Fungal Spore Pods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79357] = { id = 79357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Removing the Cap", description = "Aemara's mention of a large fungarian planting fungal pods worries me. Gotta be someting down in dat cave.\n\nWe can't just be waitin' for the fungarians to attack with a nest of mind-controlled beasts. We gotta prune dat plan before it has a chance to bloom.\n\nGet to Pillar-nest Vosh and kill that fungarian leader!", completion = "That fungarian leader's plans are over, and the camp is safe again. Thank you, friend.", objectives = "Kill Agaricus Festerbloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79367] = { id = 79367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Nebb in Need", description = "You! You no spider. Please, must help before spiders come again. \n\nNebb know Chittering Den. Never seen spiders here before. Eat grubs, eat kobolds. But spiders dark things from dark places. Hate light.\n\nCan't leave post. You take candles, yes? Light up barricade. Keep spiders away.", progress = "Keep away dark. Keep away spiders.", completion = "Good. We safe for now.", objectives = "Collect the Bundle of Candles and place candles along the barricade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79368] = { id = 79368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hair of the Spider", description = "Light good, but more to do. \n\nSpiders came from everywhere. Nebb quick, Nebb heard them. But friend Snubjaw... he bit. Sick now.\n\nNebb might know a way, yes, turn venom into cure. Use bite to cure bite.\n\nBring venom. Hurry now!", progress = "You have venom?", completion = "Yes, nasty venom make perfect cure.", objectives = "Collect 12 Undercrawler Venom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79369] = { id = 79369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protecting the Harvest", description = "Nebb young, no see past own snout. If harvest lost, many kobolds lost. Not just Snubjaw.\n\nCan no waste time. Kobolds starve if spiders gobble grubs and eggs.\n\nSave them, gather eggs. As many as can carry before spiders snatch all.", progress = "Bring eggs, we save harvest.", completion = "Many lost. With these, next grub season possible.", objectives = "Collect 20 Grub Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79370] = { id = 79370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Poultice for Poison", description = "Little venom, little wax...\n\n<Nebb reaches into his pouch and gives you a handful of thick, pungent wax.>\n\nYes, yes, should work. Finest poultice, family recipe. Hurry now, give to Snubjaw. He feel right better.", progress = "Poultice fix him right up.", completion = "No work, he worse! But why?", objectives = "Use Nebb's Poultice on Snubjaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79371] = { id = 79371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Royal Cure", description = "Poultice no work! Wax right, venom wrong?\n\nYes... yes! Strongest cure need strongest venom. Nebb saw crawler. She queen in red and black, too big to bother with kobolds. Queen smelled juicy grubs and skittered for cave.\n\nNow you must follow. Collect royal venom. Please, Snubjaw have little time.", progress = "Queen venom must work.", completion = "It work! He no green now. Thank you, thank you for saving friend Snubjaw.", objectives = "Collect Queen Rickiticka's Venom to make a new poultice for Snubjaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79372] = { id = 79372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Clutch of Hope", description = "<The broodmother lies dead, coiled around a single egg. She gave her life to keep it from the spiders.\n\nYou should take it to Nebb. He and the other Grubtenders would know what to do with it.>", progress = "What this, another egg?", completion = "This not just any egg. Mother egg.\n\n<Nebb takes the egg from you. He holds it with reverence.>\n\nWith this, grubs not just survive. They thrive. Thank you. We protect.", objectives = "Bring the egg to Nebb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79379] = { id = 79379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain's Orders: No Prey, No Pay" }
quests[79380] = { id = 79380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bog Beast Banishment" }
quests[79381] = { id = 79381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain's Orders: X Marks the Spot" }
quests[79382] = { id = 79382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain's Orders: Plunderstudy" }
quests[79383] = { id = 79383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Web of Manipulation - Activate" }
quests[79432] = { id = 79432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's About Time", description = "Your timing is serendipitous. I require your assistance.\n\nNot all infinites have seen what Nozdormu has shown me. Not all would agree even if they had. Archaios is one such detractor. He must be eliminated.", progress = "The other infinites jeopardize our mission. We cannot let them wreak havoc on the timeways.", completion = "Reckless. They have unraveled the threads of time!", objectives = "Slay Archaios the Artificer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79433] = { id = 79433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Expert Advice", description = "Take this spool to Moratari. Perhaps she can make sense of this relic.", completion = "What do you have there? This artifact is absolutely radiating with temporal power!\n\n<Moratari leans in for a closer look.>\n\nAha! Even more brilliant than I thought! Assimilating the latent temporal signatures of unraveled causalities...\n\nSorry, I am getting ahead of myself. Allow me to explain.", objectives = "Speak with Moratari.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79434] = { id = 79434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weave It To Me", description = "The other infinites are not as judicious in their treatment of the timeline. They have rather torn through time in their reckless opposition to our efforts.\n\nThough we cannot simply mend the timeways, we may yet repurpose its loose threads.\n\nReclaim the threads of time from our enemies and we shall weave you a cloak worthy of the Infinite Dragonflight.", progress = "It is our duty as responsible scholars to clean up after ourselves... and others.\n\n<Moratari glances toward the distant ravagers with an annoyed expression.>\n\nWe cannot let stray threads continue to create temporal anomalies.", completion = "Excellent. Now we just need something to hold them together.", objectives = "Collect 3 Threads of Time from Infinite Ravagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79435] = { id = 79435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Hours Is Yours", description = "Horos, our antiquities collector, should have a chronobadge you can use to fasten together the temporal threads you collected.\n\nWith the chronobadge, Momentus can craft the threads into a powerful cloak for you to wear!", progress = "That cloak will be able to absorb loose threads of time, adding them to its own magic. The prospect of infinite power is enticing, is it not? Just don't let it go to your head.\n\nLet it go to your cloak instead!\n\n<Moratari giggles.>", completion = "Wonderful! Try this on.\n\nWith the temporal magic in this cloak, you will be able to see and collect the scattered threads of time.\n\nThere is no limit to how many you can have--the possibilities are infinite!", objectives = "Purchase a Chronobadge from Horos, then speak with Momentus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79437] = { id = 79437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knot My Problem", description = "These temporal anomalies are getting out of control. Normally, our research does not unravel the timeline this much--I suspect the other infinites are to blame.\n\nUse this chronostabilizer to zip up the frayed rifts.\n\nBe aware--this may briefly create even more anomalies. I trust you know how to handle them.", progress = "Every moment moves us toward a new possibility. With every fight, we learn and change.", completion = "Change begets change. Such is the way of the infinites. It is our duty to choose which changes are worth preserving.", objectives = "Use the Chronostabilizer to close 3 Time Rifts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79438] = { id = 79438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goodbyes Are Hard When You Live Forever", description = "We have one last anomaly to deal with here before we can study the history of Pandaria.\n\nHelp us stabilize the timeway and secure our mission.", progress = "Dealing with paradoxes can be difficult, but these are the risks we accept.", completion = "Thank you for your aid in battle, {name}. I am sure Eternus will have need of you yet!", objectives = "Defeat Eratus, the Unwoven Paradox.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79440] = { id = 79440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recalling the War", description = "Our operations here are secure. For now, anyway!\n\nIt is time for you to begin your journey to the past so that we may observe how history unfolded.\n\nSpeak with Eternus if you have any final questions about our mission. She can show you how these events began.", completion = "Good luck, {name}. We will be watching you.", objectives = "Ask Eternus to show you the events of the past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79448] = { id = 79448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave No Flightstone Unturned", description = "It's so exciting to be in Valdrakken! Cuzolth and I have never been here before. And it's everything we hoped it would be. Some of the others have even introduced themselves. They actually thanked us for our work studying Flightstones and Crests. That's every researcher's dream!\n\nSo I need your help again. Could you find some Flightstones and a new piece of adventuring gear? Then come back to Cuzolth for an upgrade? It would really help us solidify our new position here.", progress = "There's no need to hurry. But if you wouldn't mind hurrying anyway...", completion = "My friend! You are truly a supportive breeze in flight. Please take these tokens of thanks.", objectives = "Acquire 50 Flightstones by defeating unique creatures, conquering dungeons and raids, completing world activities, or by looting caches. Then speak to Cuzolth and upgrade a piece of Season 4 equipment using Flightstones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79453] = { id = 79453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awakened Crests, Unlimited Possibilities", description = "Your help is always appreciated, and now you know you can easily upgrade lower-level gear right here.\n\nOf course, I'm sure you know that Flightstones can only go so far. You need Awakened Crests to upgrade powerful adventuring gear. Much like Flightstones, these Crests are rewarded through many different activities. Awakened Crests have four tiers, and more dangerous tasks reward you with higher-tier crests.\n\nBring me fifteen Whelpling's Awakened Crests, and we can help you upgrade some gear further.", progress = "If you're having a hard time finding Whelpling's Awakened Crests, you can search for hidden treasures around the Dragon Isles. There's no shortage of those!", completion = "This is wonderful. I'm so excited for you to grow in power!", objectives = "Acquire 15 Whelpling's Awakened Crests by defeating unique creatures, conquering dungeons and raids, completing world activities, or by looting caches. Then return to Vaskarn in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79469] = { id = 79469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lurking Below" }
quests[79470] = { id = 79470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waters of War" }
quests[79471] = { id = 79471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleak Sand" }
quests[79475] = { id = 79475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charging Up That Hill", description = "Before we use the conduit to summon the stormrooks, we need to recharge it. There are other, gentler ways to do this but... we have to work with what's on hand. \n\nThe way to the peak is overrun with hostile elementals cast off from the storm. If we send them back to their plane, we can capture their residual energy and re-energize the conduit.\n\nWhile you work on recharging the conduit, we will go ahead and prepare for the ritual at the peak.", progress = "Have you finished charging the conduit?", completion = "The conduit! Do you feel that? It's humming--no, it's practically singing with power. \n\nI've heard this song before, late at night in the Stormperch's rookery. When the storms would come and lightning flashed across the bay, the rooks would answer just like this. \n\nYou can't hear it?", objectives = "Charge the conduit with elemental energy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79476] = { id = 79476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heeding the Call", description = "Earthen from across the island have been drawn to this place. Kind of a strange coincidence you'd show up now too.\n\nMaybe it's because Baelgrim's gone or... a new Stormward's coming. Or it could just be barometric pressure...\n\nBah! There's time enough to spin wild theories later. Right now, we need to assist the pilgrims that have foolishly attempted the summit unprepared. We can't be worrying about them while we try to summon the stormrooks.", progress = "These earthen pilgrims seem intent on reaching the peak. I hope we can keep them safe.", completion = "If the storm summoned these earthen here, does that mean they have a role to play in what comes next? \n\nWe've directed them to hole up in the cave near the peak for now. I'm not sure what's next for them--or any of us.", objectives = "Help 8 Stranded Pilgrims on the mountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79477] = { id = 79477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strays", description = "Kurdran Wildhammer has come to train the new Stormriders in aerial maneuvers. Thrall says his clan rides gryphons--much like the Stormriders ride stormrooks--so he should be of great help to us.\n\nUnfortunately, a few of our new recruits seem to have, uh, wandered off with their stormrooks. I wanted them to have a chance to bond, but it's time to come home.\n\nWould you mind rounding them up? Thrall and I are putting together something special for these \"rookies\" lessons.", progress = "You found those stray rookies yet?", completion = "Right then! Good on ye for roundin' everyone up. We're lookin' tae start formal flight trainin' and we wouldn't want any stragglers, now would we? \n\nI'm eager to see what these stormrooks--and the earthen--can do.", objectives = "Round up the stray recruits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79480] = { id = 79480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paying Respects", description = "Please excuse my absence. It was never my intention to turn my back on the Stormriders, then or now. But I needed to come here and pay my respects to Baelgrim.\n\nUnfortunately, these blasted nerubians are still lingering. I think they're searching for something, but I don't know what. Whatever their reasons, I cannot abide them lurking where Baelgrim fell.", progress = "I don't know who or what these nerubians are searching for, but they defile this place with their presence. Clear them out.", completion = "This is a gift. Baelgrim may be gone, but his stormrook seems ready to carry on his fight. It's been a long time since I've felt such a connection. Such purpose. I don't intend to turn my back a second time.", objectives = "Clear out nerubian stragglers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79481] = { id = 79481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tending to the Terrified", description = "All happen so fast. One moment, we gathering eggs and grubs. Next, spiders swarming.\n\nNebb drag me here, many others trapped. Caught in webs, soon to be feasts. Must save the Grubtenders. \n\nWe tenders, not fighters. Do not let friends become meals.", completion = "Aha, Grubtenders free! They survive to harvest again.", objectives = "Rescue 6 Terrified Grubtenders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79489] = { id = 79489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gems of Power", description = "You have found a gem that improves your combat capabilities when socketed into a prismatic socket found in your chest or leg armor.\n\nSocket this Chipped Deadly Sapphire into your equipment to increase your Critical Strike chance.You will learn:", objectives = "[Shift Right Click your chest or leg armor and socket the Chipped Deadly Sapphire.]", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79504] = { id = 79504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dripsy Forgot Her Candle", description = "Gather round, tenderfoots, and Granny Scribbles tell you story.\n\nStory of what happen when Dripsy forgot her candle.\n\nDripsy little tenderfoot, like you, who wander away from tribe...", progress = "You listen too. Maybe learn something.", completion = "Important not forget candle. Something every little kobold need learn.", objectives = "Relive Granny Scribbles' story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79505] = { id = 79505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chomps and the Cave-In", description = "Sit down, stop talk, and Granny Scribbles tell you story. Story that maybe save life one day.\n\nAbout what happen when not listen to old, wise kobold. Like me!\n\nStory of Chomps and the cave-in...", progress = "Important pay attention. Following along?", completion = "You not too old respect elders, {name}. Even if not kobold.", objectives = "Relive Granny Scribbles' story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79507] = { id = 79507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Day the Stoneheads Came", description = "What? Want scary story?\n\nYou ask. Granny Scribbles give what want. Maybe then sit still like good tenderfoots.\n\nScariest story Granny know, yes. Story about the day the stoneheads came...", progress = "Hope story not too scary for you.", completion = "<Granny Scribbles gestures around to the room.>\n\nNot all stoneheads bad, seems like.\n\nStill, little kobold need know what happen. What can happen.", objectives = "Relive Granny Scribbles' story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79508] = { id = 79508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mipsy Mole-Rider", description = "Time for happy story. Not all days bad.\n\n<Granny Scribbles gently scratches Ol' Snorler behind his ears.>\n\nTell story of how be friends with moles. Story of Mipsy mole-rider...", progress = "You listening?", completion = "Tenderfoots always fan of that one.\n\nWhat you think of mole? Think ride good as Mipsy?", objectives = "Relive Granny Scribbles' story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[79510] = { id = 79510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wickless Candle", description = "Now tell story of very far place called \"surface\". New friend from there, yes, so they know what Granny Scribbles talk about.\n\n<Granny Scribbles nods sagely as she points you out.>\n\nStory of how kobold discover it long go, and what find when do. Story of the wickless candle...", progress = "Sound like place you know?", completion = "You not bad listener, {name}. Name you honorary tenderfoot, Granny Scribbles thinks.\n\nMaybe next time you tell Granny Scribbles story. Never too old to learn new one.", objectives = "Relive Granny Scribbles' story.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
